// SHADOW NINJA — shared config and math helpers

export const TAU = Math.PI * 2;
export const BASE_H = 720;
export const GROUND_Y = 624;
export const WORLD_W = 3000;

export const PLATFORMS = [
  { x: 430, y: 476, w: 250, h: 18 },
  { x: 820, y: 372, w: 210, h: 18 },
  { x: 1210, y: 486, w: 300, h: 18 },
  { x: 1660, y: 392, w: 250, h: 18 },
  { x: 2070, y: 480, w: 260, h: 18 },
  { x: 2480, y: 380, w: 200, h: 18 },
  { x: 2760, y: 492, w: 170, h: 18 },
];

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const sign = (v) => (v < 0 ? -1 : 1);
export const dist2 = (ax, ay, bx, by) => {
  const dx = bx - ax, dy = by - ay;
  return dx * dx + dy * dy;
};
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInCubic = (t) => t * t * t;
export const easeOutBack = (t) => {
  const c = 1.70158;
  return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2);
};
export const smooth = (t) => t * t * (3 - 2 * t);

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hashNoise(n) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function glowCircle(ctx, x, y, r, inner, outer = 'rgba(0,0,0,0)') {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
}

export function rgba(hex, a) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
}

export function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function circleRect(cx, cy, cr, r) {
  const nx = clamp(cx, r.x, r.x + r.w);
  const ny = clamp(cy, r.y, r.y + r.h);
  return dist2(cx, cy, nx, ny) <= cr * cr;
}

// SHADOW NINJA — procedural audio (WebAudio, no asset downloads)

export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfxBus = null;
    this.musicBus = null;
    this.comp = null;
    this.noise = null;
    this.muted = false;
    this.mode = 'menu';
    this.step = 0;
    this.nextNote = 0;
    this.timer = null;
    this.running = false;
    this.paused = false;
    this.masterLevel = 0.62;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
    } catch {
      return;
    }
    const ctx = this.ctx;
    this.comp = ctx.createDynamicsCompressor();
    this.comp.threshold.value = -16;
    this.comp.knee.value = 18;
    this.comp.ratio.value = 5;
    this.comp.attack.value = 0.004;
    this.comp.release.value = 0.24;

    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : this.masterLevel;

    this.sfxBus = ctx.createGain();
    this.sfxBus.gain.value = 0.9;
    this.musicBus = ctx.createGain();
    this.musicBus.gain.value = 0.26;

    this.sfxBus.connect(this.master);
    this.musicBus.connect(this.master);
    this.master.connect(this.comp);
    this.comp.connect(ctx.destination);

    // shared noise buffer
    const len = Math.floor(ctx.sampleRate * 1.4);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noise = buf;

    this.running = true;
    this.nextNote = ctx.currentTime + 0.1;
    this.timer = setInterval(() => this.schedule(), 90);
    this.startDrone();
  }

  setMasterLevel(v) {
    this.masterLevel = v;
    if (this.master && !this.muted) {
      this.master.gain.setTargetAtTime(v, this.ctx.currentTime, 0.1);
    }
  }

  toggleMute() {
    this.muted = !this.muted;
    if (this.master) {
      this.master.gain.setTargetAtTime(this.muted ? 0 : this.masterLevel, this.ctx.currentTime, 0.05);
    }
    return this.muted;
  }

  duck(on) {
    this.paused = on;
    if (!this.musicBus || !this.ctx) return;
    const target = on ? 0.07 : 0.26;
    this.musicBus.gain.setTargetAtTime(target, this.ctx.currentTime, 0.25);
  }

  setMode(mode) {
    if (this.mode === mode) return;
    this.mode = mode;
    this.step = 0;
    if (this.ctx) this.nextNote = Math.max(this.nextNote, this.ctx.currentTime + 0.05);
  }

  // ---------- low level synth ----------
  env(gainNode, t0, attack, decay, peak, sustain = 0.0001) {
    const g = gainNode.gain;
    g.cancelScheduledValues(t0);
    g.setValueAtTime(0.0001, t0);
    g.exponentialRampToValueAtTime(Math.max(peak, 0.0002), t0 + attack);
    g.exponentialRampToValueAtTime(Math.max(sustain, 0.0001), t0 + attack + decay);
  }

  noiseBurst(t0, dur, { volume = 0.4, type = 'bandpass', freq = 1200, q = 1.2, sweep = 0, dest = null } = {}) {
    const ctx = this.ctx;
    if (!ctx) return;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filt = ctx.createBiquadFilter();
    filt.type = type;
    filt.frequency.setValueAtTime(freq, t0);
    if (sweep) filt.frequency.exponentialRampToValueAtTime(Math.max(60, sweep), t0 + dur);
    filt.Q.value = q;
    const g = ctx.createGain();
    this.env(g, t0, 0.005, dur, volume);
    src.connect(filt).connect(g).connect(dest || this.sfxBus);
    src.start(t0);
    src.stop(t0 + dur + 0.05);
  }

  tone(t0, dur, { type = 'sine', freq = 440, freqEnd = null, volume = 0.3, attack = 0.005, dest = null, detune = 0 } = {}) {
    const ctx = this.ctx;
    if (!ctx) return;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t0);
    if (freqEnd) o.frequency.exponentialRampToValueAtTime(Math.max(20, freqEnd), t0 + dur);
    o.detune.value = detune;
    const g = ctx.createGain();
    this.env(g, t0, attack, dur, volume, 0.0001);
    o.connect(g).connect(dest || this.sfxBus);
    o.start(t0);
    o.stop(t0 + dur + 0.06);
  }

  // ---------- SFX ----------
  sfx(name, intensity = 1) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'slash':
        this.noiseBurst(t, 0.13, { volume: 0.22 * intensity, freq: 2400, sweep: 420, q: 2.4 });
        this.tone(t, 0.1, { type: 'triangle', freq: 620, freqEnd: 240, volume: 0.055 * intensity });
        break;
      case 'slashHeavy':
        this.noiseBurst(t, 0.22, { volume: 0.3, freq: 1800, sweep: 180, q: 1.8 });
        this.tone(t, 0.22, { type: 'sawtooth', freq: 180, freqEnd: 60, volume: 0.08 });
        break;
      case 'hit':
        this.noiseBurst(t, 0.09, { volume: 0.32, type: 'lowpass', freq: 900, sweep: 180, q: 0.8 });
        this.tone(t, 0.12, { type: 'sine', freq: 150, freqEnd: 52, volume: 0.34 });
        this.tone(t, 0.06, { type: 'square', freq: 780, freqEnd: 300, volume: 0.035 });
        break;
      case 'kill':
        this.tone(t, 0.3, { type: 'sine', freq: 120, freqEnd: 38, volume: 0.35 });
        this.noiseBurst(t, 0.28, { volume: 0.24, type: 'lowpass', freq: 1400, sweep: 120 });
        this.tone(t + 0.03, 0.2, { type: 'triangle', freq: 880, freqEnd: 1320, volume: 0.05 });
        break;
      case 'jump':
        this.tone(t, 0.14, { type: 'sine', freq: 280, freqEnd: 620, volume: 0.1 });
        this.noiseBurst(t, 0.1, { volume: 0.06, type: 'highpass', freq: 1200 });
        break;
      case 'doubleJump':
        this.tone(t, 0.18, { type: 'triangle', freq: 420, freqEnd: 900, volume: 0.1 });
        this.noiseBurst(t, 0.16, { volume: 0.09, type: 'bandpass', freq: 1800, sweep: 3000, q: 3 });
        break;
      case 'dash':
        this.noiseBurst(t, 0.24, { volume: 0.26, type: 'bandpass', freq: 900, sweep: 2600, q: 1.1 });
        this.tone(t, 0.16, { type: 'sine', freq: 90, freqEnd: 45, volume: 0.14 });
        break;
      case 'hurt':
        this.noiseBurst(t, 0.24, { volume: 0.34, type: 'lowpass', freq: 800, sweep: 90 });
        this.tone(t, 0.26, { type: 'sawtooth', freq: 220, freqEnd: 60, volume: 0.18 });
        this.tone(t + 0.02, 0.2, { type: 'square', freq: 110, freqEnd: 44, volume: 0.08 });
        break;
      case 'pickup':
        this.tone(t, 0.16, { type: 'sine', freq: 660, volume: 0.1 });
        this.tone(t + 0.07, 0.22, { type: 'sine', freq: 990, volume: 0.09 });
        break;
      case 'parry':
        this.tone(t, 0.18, { type: 'triangle', freq: 1900, freqEnd: 1400, volume: 0.14 });
        this.tone(t + 0.01, 0.26, { type: 'sine', freq: 2600, volume: 0.06 });
        this.noiseBurst(t, 0.08, { volume: 0.18, type: 'highpass', freq: 3400 });
        break;
      case 'burst':
        this.noiseBurst(t, 0.7, { volume: 0.4, type: 'bandpass', freq: 300, sweep: 4200, q: 0.8 });
        this.tone(t, 0.75, { type: 'sawtooth', freq: 60, freqEnd: 32, volume: 0.24 });
        this.tone(t + 0.06, 0.6, { type: 'triangle', freq: 320, freqEnd: 140, volume: 0.12 });
        break;
      case 'arrow':
        this.noiseBurst(t, 0.18, { volume: 0.13, type: 'bandpass', freq: 1800, sweep: 700, q: 4 });
        break;
      case 'slam':
        this.tone(t, 0.5, { type: 'sine', freq: 78, freqEnd: 26, volume: 0.45 });
        this.noiseBurst(t, 0.36, { volume: 0.35, type: 'lowpass', freq: 500, sweep: 60 });
        break;
      case 'roar':
        this.tone(t, 0.9, { type: 'sawtooth', freq: 90, freqEnd: 34, volume: 0.18 });
        this.tone(t + 0.05, 0.8, { type: 'square', freq: 64, freqEnd: 28, volume: 0.08 });
        this.noiseBurst(t, 0.9, { volume: 0.28, type: 'bandpass', freq: 420, sweep: 90, q: 1.2 });
        break;
      case 'wave':
        this.tone(t, 0.4, { type: 'sine', freq: 220, volume: 0.08 });
        this.tone(t + 0.16, 0.5, { type: 'sine', freq: 330, volume: 0.07 });
        this.tone(t + 0.32, 0.7, { type: 'sine', freq: 440, volume: 0.06 });
        break;
      case 'combo':
        this.tone(t, 0.1, { type: 'triangle', freq: 720 + Math.min(intensity, 8) * 70, volume: 0.045 });
        break;
      case 'click':
        this.tone(t, 0.05, { type: 'square', freq: 320, volume: 0.035 });
        break;
      case 'death':
        this.tone(t, 1.5, { type: 'sawtooth', freq: 140, freqEnd: 26, volume: 0.18 });
        this.tone(t, 1.6, { type: 'sine', freq: 60, freqEnd: 22, volume: 0.26 });
        this.noiseBurst(t, 1.2, { volume: 0.2, type: 'lowpass', freq: 600, sweep: 60 });
        break;
      case 'victory':
        [0, 0.18, 0.36, 0.7].forEach((d, i) => {
          this.tone(t + d, 0.9 - i * 0.1, { type: 'sine', freq: [262, 330, 392, 523][i], volume: 0.09 });
        });
        break;
    }
  }

  startDrone() {
    const ctx = this.ctx;
    if (!ctx || this.droneStarted) return;
    this.droneStarted = true;
    const g = ctx.createGain();
    g.gain.value = 0.0001;
    const filt = ctx.createBiquadFilter();
    filt.type = 'lowpass';
    filt.frequency.value = 220;
    filt.Q.value = 2;
    const oscs = [55, 82.41, 110.2].map((f, i) => {
      const o = ctx.createOscillator();
      o.type = i === 1 ? 'triangle' : 'sawtooth';
      o.frequency.value = f;
      o.detune.value = (i - 1) * 7;
      o.connect(filt);
      o.start();
      return o;
    });
    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 60;
    lfo.connect(lfoGain).connect(filt.frequency);
    lfo.start();
    filt.connect(g).connect(this.musicBus);
    g.gain.setTargetAtTime(0.06, ctx.currentTime, 2.5);
    this.drone = { g, oscs };
  }

  schedule() {
    if (!this.running || !this.ctx || this.paused) return;
    const ctx = this.ctx;
    if (this.nextNote < ctx.currentTime) this.nextNote = ctx.currentTime + 0.05;
    const tempo = this.mode === 'boss' ? 0.16 : this.mode === 'battle' ? 0.23 : 0.34;
    while (this.nextNote < ctx.currentTime + 0.5) {
      this.playStep(this.step, this.nextNote);
      this.step = (this.step + 1) % 32;
      this.nextNote += tempo;
    }
  }

  playStep(step, t) {
    const battle = this.mode === 'battle' || this.mode === 'boss';
    const boss = this.mode === 'boss';
    const scale = [220, 261.63, 293.66, 329.63, 392, 440, 523.25];

    // taiko heartbeat
    if (battle) {
      if (step % 8 === 0 || step % 8 === 3) {
        this.tone(t, 0.42, { type: 'sine', freq: boss ? 88 : 76, freqEnd: 34, volume: boss ? 0.2 : 0.13, dest: this.musicBus });
        this.noiseBurst(t, 0.14, { volume: 0.07, type: 'lowpass', freq: 320, sweep: 60, dest: this.musicBus });
      }
      if (boss && step % 4 === 2) {
        this.tone(t, 0.18, { type: 'sine', freq: 110, freqEnd: 50, volume: 0.1, dest: this.musicBus });
      }
    } else if (step % 16 === 0) {
      this.tone(t, 0.5, { type: 'sine', freq: 66, freqEnd: 32, volume: 0.09, dest: this.musicBus });
    }

    // koto / shamisen plucks
    const kotoPattern = battle
      ? [0, 3, 6, 10, 14, 18, 22, 26]
      : [2, 9, 17, 24, 28];
    if (kotoPattern.includes(step) && Math.random() < (battle ? 0.92 : 0.6)) {
      const note = scale[(step * 3 + (step % 5)) % scale.length] * (boss ? 0.5 : 1);
      this.koto(t, note, battle ? 0.055 : 0.04);
    }

    // sparse flute phrases
    if (battle && step === 18 && Math.random() < 0.5) {
      this.flute(t, scale[(Math.random() * scale.length) | 0] * 2, 1.4);
    }
    if (boss && step % 16 === 7) {
      this.koto(t, scale[step % scale.length] * 0.5, 0.075);
    }
  }

  koto(t, freq, vol) {
    const ctx = this.ctx;
    if (!ctx) return;
    const o = ctx.createOscillator();
    const o2 = ctx.createOscillator();
    const g = ctx.createGain();
    const filt = ctx.createBiquadFilter();
    o.type = 'triangle';
    o2.type = 'sine';
    o.frequency.value = freq;
    o2.frequency.value = freq * 2.01;
    filt.type = 'lowpass';
    filt.frequency.setValueAtTime(4200, t);
    filt.frequency.exponentialRampToValueAtTime(600, t + 0.45);
    this.env(g, t, 0.004, 0.55, vol);
    o.connect(filt);
    o2.connect(filt);
    filt.connect(g).connect(this.musicBus);
    o.start(t); o2.start(t);
    o.stop(t + 0.7); o2.stop(t + 0.7);
  }

  flute(t, freq, dur) {
    const ctx = this.ctx;
    if (!ctx) return;
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    const lfo = ctx.createOscillator();
    const lg = ctx.createGain();
    o.type = 'sine';
    o.frequency.value = freq;
    lfo.frequency.value = 5.2;
    lg.gain.value = 4;
    lfo.connect(lg).connect(o.frequency);
    const filt = ctx.createBiquadFilter();
    filt.type = 'lowpass';
    filt.frequency.value = 2200;
    this.env(g, t, 0.35, dur, 0.035);
    o.connect(filt).connect(g).connect(this.musicBus);
    o.start(t); lfo.start(t);
    o.stop(t + dur + 0.4); lfo.stop(t + dur + 0.4);
  }
}

export const sound = new SoundEngine();

// SHADOW NINJA — unified keyboard, touch, and gamepad input

const KEYMAP = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  Space: 'jump',
  KeyJ: 'attack', KeyX: 'attack',
  KeyK: 'dash', ShiftLeft: 'dash', ShiftRight: 'dash',
  KeyL: 'burst', KeyE: 'burst',
  Escape: 'pause', KeyP: 'pause',
  KeyM: 'mute',
  KeyR: 'restart',
  Enter: 'confirm',
};

export class Input {
  constructor() {
    this.keys = new Set();
    this.actions = new Set();
    this.edges = new Set();
    this.touch = false;
    this.joyX = 0;
    this.joyY = 0;
    this.joyActive = false;
    this.gamepad = null;
    this.padPrev = [];
    this.enabled = true;
    this._bindKeyboard();
    this._bindGamepad();
    this._bindTouch();
    this._bindMouse();
  }

  get coarse() {
    return (
      (window.matchMedia && window.matchMedia('(pointer: coarse)').matches) ||
      'ontouchstart' in window ||
      navigator.maxTouchPoints > 0
    );
  }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      const action = KEYMAP[e.code];
      if (!action) return;
      if (
        ['jump', 'attack', 'dash', 'burst', 'left', 'right', 'up', 'down', 'pause'].includes(action)
      ) {
        e.preventDefault();
      }
      if (e.repeat) return;
      this.keys.add(action);
      this.actions.add(action);
      this.edges.add(action);
    });
    window.addEventListener('keyup', (e) => {
      const action = KEYMAP[e.code];
      if (!action) return;
      this.keys.delete(action);
      this.actions.delete(action);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.actions.clear();
    });
  }

  _bindGamepad() {
    window.addEventListener('gamepadconnected', (e) => {
      this.gamepad = e.gamepad.index;
    });
    window.addEventListener('gamepaddisconnected', () => {
      this.gamepad = null;
    });
  }

  _bindMouse() {
    window.addEventListener('mousedown', (e) => {
      if (e.target && e.target.id === 'game' && e.button === 0) {
        this.actions.add('attack');
        this.edges.add('attack');
      }
    });
  }

  _bindTouch() {
    this.touch = this.coarse;
    const base = document.getElementById('joystick');
    const knob = document.getElementById('joystick-knob');
    if (!base || !knob) return;
    const max = 44;
    let id = null;
    let ox = 0, oy = 0;

    const apply = (e) => {
      let dx = e.clientX - ox;
      let dy = e.clientY - oy;
      const len = Math.hypot(dx, dy);
      if (len > max) {
        dx = (dx / len) * max;
        dy = (dy / len) * max;
      }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      const nx = dx / max;
      const ny = dy / max;
      this.joyX = Math.abs(nx) > 0.16 ? nx : 0;
      this.joyY = Math.abs(ny) > 0.2 ? ny : 0;
      if (this.joyX !== 0 || this.joyY !== 0) this.joyActive = true;
    };

    base.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      id = e.pointerId;
      base.setPointerCapture(id);
      const r = base.getBoundingClientRect();
      ox = r.left + r.width / 2;
      oy = r.top + r.height / 2;
      base.classList.add('active');
      apply(e);
    });
    base.addEventListener('pointermove', (e) => {
      if (id !== e.pointerId) return;
      e.preventDefault();
      apply(e);
    });
    const end = (e) => {
      if (id !== e.pointerId) return;
      id = null;
      this.joyX = 0;
      this.joyY = 0;
      this.joyActive = false;
      knob.style.transform = 'translate(0px, 0px)';
      base.classList.remove('active');
    };
    base.addEventListener('pointerup', end);
    base.addEventListener('pointercancel', end);
    base.addEventListener('lostpointercapture', end);

    document.querySelectorAll('[data-action]').forEach((btn) => {
      const action = btn.dataset.action;
      let pressed = false;
      const down = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (pressed) return;
        pressed = true;
        try { btn.setPointerCapture(e.pointerId); } catch {}
        this.actions.add(action);
        this.edges.add(action);
        btn.classList.add('pressed');
      };
      const up = (e) => {
        if (!pressed) return;
        e.preventDefault();
        pressed = false;
        this.actions.delete(action);
        btn.classList.remove('pressed');
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('pointerleave', up);
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
    });
  }

  pollGamepad() {
    if (!navigator.getGamepads) return;
    const pads = navigator.getGamepads();
    let pad = null;
    for (const p of pads) {
      if (p && p.connected) { pad = p; break; }
    }
    if (!pad) return;
    const axis = pad.axes[0] || 0;
    if (Math.abs(axis) > 0.22) {
      this.joyX = axis;
      if (axis < -0.4 && !this.padPrev[14]) { this.actions.add('left'); this.edges.add('left'); }
      if (axis > 0.4 && !this.padPrev[15]) { this.actions.add('right'); this.edges.add('right'); }
    }
    const btnMap = { 0: 'jump', 2: 'attack', 1: 'dash', 3: 'burst', 9: 'pause' };
    for (const [idx, action] of Object.entries(btnMap)) {
      const b = pad.buttons[idx];
      const down = b && (b.pressed || b.value > 0.4);
      if (down && !this.padPrev[idx]) {
        this.edges.add(action);
        this.actions.add(action);
      }
      if (!down && this.padPrev[idx]) this.actions.delete(action);
      this.padPrev[idx] = down;
    }
  }

  beginFrame() {
    this.pollGamepad();
  }

  down(action) {
    if (this.keys.has(action) || this.actions.has(action)) return true;
    if (action === 'left' && this.joyX < -0.2) return true;
    if (action === 'right' && this.joyX > 0.2) return true;
    if (action === 'up' && this.joyY < -0.35) return true;
    if (action === 'down' && this.joyY > 0.35) return true;
    return false;
  }

  pressed(action) {
    return this.edges.has(action);
  }

  endFrame() {
    this.edges.clear();
  }

  moveX() {
    let x = this.joyX;
    if (this.down('left')) x -= 1;
    if (this.down('right')) x += 1;
    return Math.max(-1, Math.min(1, x));
  }

  moveY() {
    let y = this.joyY;
    if (this.down('up')) y -= 1;
    if (this.down('down')) y += 1;
    return Math.max(-1, Math.min(1, y));
  }

  rumble(strength = 0.4) {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    for (const p of pads) {
      if (p && p.vibrationActuator) {
        try {
          p.vibrationActuator.playEffect('dual-rumble', {
            duration: 90,
            strongMagnitude: strength,
            weakMagnitude: strength * 0.5,
          });
        } catch {}
      }
    }
  }
}

// SHADOW NINJA — particles, slash trails, afterimages, floating text, screen shake

import { TAU, rand, randInt, pick, clamp, lerp, easeOutCubic, hashNoise } from './utils.js';

const MAX_PARTICLES = 560;

export class FX {
  constructor() {
    this.particles = [];
    this.texts = [];
    this.slashes = [];
    this.ghosts = [];
    this.trauma = 0;
    this.shakeSeed = Math.random() * 1000;
    this.flash = 0;
    this.flashColor = '255,255,255';
  }

  reset() {
    this.particles.length = 0;
    this.texts.length = 0;
    this.slashes.length = 0;
    this.ghosts.length = 0;
    this.trauma = 0;
    this.flash = 0;
  }

  addTrauma(v) {
    this.trauma = Math.min(1, this.trauma + v);
  }

  screenFlash(amount = 0.5, color = '255,255,255') {
    this.flash = Math.max(this.flash, amount);
    this.flashColor = color;
  }

  shakeOffset(time) {
    const t = this.trauma;
    if (t <= 0.001) return { x: 0, y: 0, rot: 0 };
    const mag = t * t;
    const s = this.shakeSeed + time * 34;
    return {
      x: (hashNoise(s) * 2 - 1) * 22 * mag,
      y: (hashNoise(s + 19.3) * 2 - 1) * 16 * mag,
      rot: (hashNoise(s + 41.7) * 2 - 1) * 0.018 * mag,
    };
  }

  spark(x, y, color, count = 6, speed = 260, opts = {}) {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      const a = opts.angle !== undefined ? opts.angle + rand(-opts.spread || -0.8, opts.spread || 0.8) : rand(0, TAU);
      const sp = speed * rand(0.35, 1.2);
      this.particles.push({
        type: 'spark',
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp + (opts.up || 0),
        life: rand(0.18, 0.5),
        max: 0.5,
        size: rand(1.2, 3.2),
        color,
        drag: 5,
        grav: opts.grav ?? 620,
        glow: true,
      });
    }
  }

  ember(x, y, color, count = 5, speed = 120, life = 1.1) {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      const a = rand(0, TAU);
      this.particles.push({
        type: 'ember',
        x: x + rand(-8, 8),
        y: y + rand(-10, 10),
        vx: Math.cos(a) * speed * rand(0.2, 1),
        vy: Math.sin(a) * speed * rand(0.2, 1) - rand(20, 80),
        life: rand(life * 0.5, life),
        max: life,
        size: rand(1.5, 4.5),
        color,
        drag: 1.4,
        grav: -20,
        glow: true,
      });
    }
  }

  petals(x, y, count = 6, color = '#ff9db7') {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      const a = rand(0, TAU);
      const sp = rand(40, 240);
      this.particles.push({
        type: 'petal',
        x, y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp - rand(30, 140),
        life: rand(0.8, 2),
        max: 2,
        size: rand(2.5, 6),
        color: pick([color, '#ffc4d4', '#e05a7a']),
        drag: 2.4,
        grav: 210,
        rot: rand(0, TAU),
        rotV: rand(-6, 6),
      });
    }
  }

  smoke(x, y, color = '120,120,150', count = 4, size = 16) {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      this.particles.push({
        type: 'smoke',
        x: x + rand(-12, 12),
        y: y + rand(-8, 8),
        vx: rand(-30, 30),
        vy: rand(-60, -10),
        life: rand(0.5, 1.2),
        max: 1.2,
        size: size * rand(0.6, 1.3),
        color,
        drag: 2,
        grav: -30,
      });
    }
  }

  dust(x, y, dir = 0, count = 3) {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      this.particles.push({
        type: 'smoke',
        x: x + rand(-6, 6),
        y,
        vx: rand(-60, 60) + dir * 60,
        vy: rand(-90, -25),
        life: rand(0.3, 0.7),
        max: 0.7,
        size: rand(6, 14),
        color: '160,160,180',
        drag: 3.5,
        grav: 40,
      });
    }
  }

  ring(x, y, color, radius = 80, width = 3, life = 0.35, startRadius = 4) {
    this.particles.push({
      type: 'ring',
      x, y,
      vx: 0, vy: 0,
      life, max: life,
      size: startRadius,
      radius,
      width,
      color,
      drag: 0,
      grav: 0,
      glow: true,
    });
  }

  shards(x, y, color, count = 6, speed = 240) {
    for (let i = 0; i < count; i++) {
      if (this.particles.length >= MAX_PARTICLES) break;
      const a = rand(0, TAU);
      this.particles.push({
        type: 'shard',
        x, y,
        vx: Math.cos(a) * speed * rand(0.3, 1),
        vy: Math.sin(a) * speed * rand(0.3, 1) - 80,
        life: rand(0.4, 0.9),
        max: 0.9,
        size: rand(3, 8),
        color,
        drag: 1.2,
        grav: 900,
        rot: rand(0, TAU),
        rotV: rand(-12, 12),
      });
    }
  }

  slash(x, y, angle, radius, color = '#7ef9ff', life = 0.22, width = 9, sweep = 1.9) {
    this.slashes.push({
      x, y, angle, radius, color, life, max: life, width, sweep, rot: 0,
    });
  }

  ghost(x, y, facing, color = '90,230,255', life = 0.28, scale = 1) {
    this.ghosts.push({ x, y, facing, color, life, max: life, scale });
  }

  text(x, y, str, color = '#fff', size = 18, opts = {}) {
    this.texts.push({
      x, y,
      vx: opts.vx ?? rand(-25, 25),
      vy: opts.vy ?? -58,
      str,
      color,
      size,
      life: opts.life ?? 0.8,
      max: opts.life ?? 0.8,
      weight: opts.weight ?? 700,
      italic: opts.italic ?? false,
    });
  }

  update(dt) {
    this.trauma = Math.max(0, this.trauma - dt * 1.6);
    this.flash = Math.max(0, this.flash - dt * 3.4);

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      if (p.type === 'ring') {
        p.size = lerp(p.size, p.radius, 1 - Math.exp(-9 * dt));
        continue;
      }
      p.vy += (p.grav || 0) * dt;
      const d = Math.exp(-(p.drag || 0) * dt);
      p.vx *= d;
      p.vy *= d;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.rotV) p.rot += p.rotV * dt;
    }

    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      if (t.life <= 0) { this.texts.splice(i, 1); continue; }
      t.x += t.vx * dt;
      t.y += t.vy * dt;
      t.vy += 45 * dt;
    }

    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.life -= dt;
      if (s.life <= 0) this.slashes.splice(i, 1);
    }

    for (let i = this.ghosts.length - 1; i >= 0; i--) {
      const g = this.ghosts[i];
      g.life -= dt;
      if (g.life <= 0) this.ghosts.splice(i, 1);
    }
  }

  drawGhosts(ctx) {
    if (!this.ghosts.length) return;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const g of this.ghosts) {
      const p = g.life / g.max;
      ctx.save();
      ctx.translate(g.x, g.y);
      ctx.scale(g.facing * g.scale, g.scale);
      ctx.globalAlpha = p * 0.45;
      ctx.fillStyle = `rgba(${g.color},${0.35 * p})`;
      ctx.beginPath();
      ctx.ellipse(0, -36, 15, 34, 0, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(0, -66, 11, 12, 0, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(6, -48);
      ctx.lineTo(-28 - (1 - p) * 30, -40 + Math.sin(p * 9) * 8);
      ctx.lineTo(-10, -34);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  }

  draw(ctx) {
    // additive particles
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      if (p.type === 'spark') {
        const len = clamp(Math.hypot(p.vx, p.vy) * 0.035, 3, 16);
        ctx.globalAlpha = a;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size * 0.7;
        ctx.lineCap = 'round';
        const ang = Math.atan2(p.vy, p.vx);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - Math.cos(ang) * len, p.y - Math.sin(ang) * len);
        ctx.stroke();
      } else if (p.type === 'ember') {
        ctx.globalAlpha = a * 0.85;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (0.4 + a * 0.8), 0, TAU);
        ctx.fill();
      } else if (p.type === 'ring') {
        const t = 1 - p.life / p.max;
        ctx.globalAlpha = (1 - t) * 0.9;
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.width * (1 - t * 0.7);
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, TAU);
        ctx.stroke();
      }
    }
    ctx.restore();

    // normal blend particles
    ctx.save();
    for (const p of this.particles) {
      const a = clamp(p.life / p.max, 0, 1);
      if (p.type === 'petal') {
        ctx.globalAlpha = a * 0.85;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, p.size, p.size * 0.45, 0, 0, TAU);
        ctx.fill();
        ctx.restore();
      } else if (p.type === 'smoke') {
        ctx.globalAlpha = a * 0.16;
        ctx.fillStyle = `rgb(${p.color})`;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1.8 - a * 0.8), 0, TAU);
        ctx.fill();
      } else if (p.type === 'shard') {
        ctx.globalAlpha = a;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.moveTo(0, -p.size);
        ctx.lineTo(p.size * 0.5, 0);
        ctx.lineTo(0, p.size);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }
    }
    ctx.restore();

    // slash arcs
    if (this.slashes.length) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      for (const s of this.slashes) {
        const t = 1 - s.life / s.max;
        const grow = easeOutCubic(clamp(t * 1.6, 0, 1));
        const alpha = Math.sin((1 - t) * Math.PI * 0.9) * 0.9;
        const r = s.radius * (0.65 + grow * 0.5);
        const start = s.angle - s.sweep / 2;
        const end = s.angle + s.sweep / 2;
        ctx.translate(s.x, s.y);
        ctx.rotate(s.rot || 0);
        for (let layer = 0; layer < 3; layer++) {
          ctx.globalAlpha = alpha * (0.85 - layer * 0.24);
          ctx.strokeStyle = layer === 2 ? '#ffffff' : s.color;
          ctx.lineWidth = (s.width - layer * 2.6) * (1 - t * 0.5);
          ctx.lineCap = 'round';
          ctx.beginPath();
          ctx.arc(0, 0, r - layer * 5, start + (1 - grow) * 0.5, end - (1 - grow) * 0.5);
          ctx.stroke();
        }
        ctx.setTransform(1, 0, 0, 1, 0, 0);
      }
      ctx.restore();
    }

    // floating combat text
    if (this.texts.length) {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      for (const t of this.texts) {
        const p = t.life / t.max;
        const pop = 1 + Math.sin(Math.min(1, (1 - p) * 3) * Math.PI) * 0.25;
        ctx.globalAlpha = Math.min(1, p * 1.8);
        ctx.font = `${t.italic ? 'italic ' : ''}${t.weight} ${Math.round(t.size * pop)}px Georgia, "Times New Roman", serif`;
        ctx.fillStyle = 'rgba(0,0,0,0.55)';
        ctx.fillText(t.str, t.x + 1.5, t.y + 2.5);
        ctx.fillStyle = t.color;
        ctx.fillText(t.str, t.x, t.y);
      }
      ctx.restore();
    }
  }
}

// SHADOW NINJA — procedural Japanese night scenery with parallax and neon

import { TAU, rand, pick, clamp, lerp, mulberry32, rgba, roundRect } from './utils.js';
import { GROUND_Y, WORLD_W } from './utils.js';

const KANJI = ['影', '忍', '侍', '月', '夜', '鬼', '夢', '刃', '風', '心', '雨', '桜'];

function makeGlow(color, size = 128) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  grd.addColorStop(0, color);
  grd.addColorStop(0.35, color.replace(/[\d.]+\)$/, '0.42)'));
  grd.addColorStop(1, color.replace(/[\d.]+\)$/, '0)'));
  g.fillStyle = grd;
  g.fillRect(0, 0, size, size);
  return c;
}

function makeLantern(color) {
  const c = document.createElement('canvas');
  c.width = 56;
  c.height = 84;
  const g = c.getContext('2d');
  const grd = g.createLinearGradient(0, 10, 0, 72);
  grd.addColorStop(0, '#2a0d10');
  grd.addColorStop(0.25, color);
  grd.addColorStop(0.55, '#ffe3aa');
  grd.addColorStop(0.8, color);
  grd.addColorStop(1, '#24080c');
  g.fillStyle = grd;
  g.beginPath();
  g.ellipse(28, 42, 16, 27, 0, 0, TAU);
  g.fill();
  g.strokeStyle = 'rgba(40,10,10,0.5)';
  g.lineWidth = 1;
  for (let i = -2; i <= 2; i++) {
    g.beginPath();
    g.ellipse(28, 42, 16 - Math.abs(i) * 0.6, 27, 0, 0, TAU);
    g.stroke();
  }
  g.strokeStyle = 'rgba(20,6,6,0.9)';
  g.lineWidth = 2.5;
  g.beginPath();
  g.moveTo(16, 16); g.lineTo(40, 16);
  g.moveTo(17, 69); g.lineTo(39, 69);
  g.stroke();
  g.fillStyle = 'rgba(255,120,80,0.9)';
  g.fillRect(26, 69, 4, 10);
  return c;
}

export class Scenery {
  constructor() {
    const rng = mulberry32(9271);
    this.rand = rng;
    this.viewW = 1280;
    this.viewH = 720;
    this.extraY = 0;
    this.time = 0;

    this.glowWarm = makeGlow('rgba(255,150,80,0.85)');
    this.glowRed = makeGlow('rgba(255,60,90,0.85)');
    this.glowCyan = makeGlow('rgba(70,240,230,0.8)');
    this.glowMoon = makeGlow('rgba(255,235,205,0.55)');
    this.lanternSprites = [makeLantern('#e85736'), makeLantern('#d94a62'), makeLantern('#e9903f')];

    this.stars = [];
    for (let i = 0; i < 90; i++) {
      this.stars.push({
        x: rng(), y: rng() * 0.62, r: 0.5 + rng() * 1.7,
        phase: rng() * TAU, speed: 0.5 + rng() * 1.6,
      });
    }

    this.ridges = [];
    const ridgeCols = ['#0b0a1c', '#0d0b21', '#100d26', '#090814'];
    for (let l = 0; l < 4; l++) {
      const pts = [];
      const base = 120 + l * 36;
      const amp = 120 - l * 20;
      for (let x = -300; x <= WORLD_W + 1400; x += 90) {
        const n =
          Math.sin(x * 0.0018 + l * 1.7) * 0.5 +
          Math.sin(x * 0.0043 + l * 2.9) * 0.28 +
          Math.sin(x * 0.011 + l) * 0.12;
        pts.push({ x, y: base + n * amp });
      }
      this.ridges.push({ pts, color: ridgeCols[l], factor: 0.035 + l * 0.012, alpha: 0.85 - l * 0.08 });
    }

    this.buildings = [];
    for (let i = 0; i < 34; i++) {
      const x = -300 + i * 155 + rng() * 70;
      const w = 60 + rng() * 120;
      const h = 40 + rng() * 200;
      const win = [];
      const cols = 2 + ((rng() * 4) | 0);
      const rows = 2 + ((rng() * 5) | 0);
      for (let c = 0; c < cols; c++) {
        for (let r = 0; r < rows; r++) {
          if (rng() < 0.42) win.push({ x: c / cols, y: r / rows, warm: rng() < 0.7 });
        }
      }
      this.buildings.push({
        x, w, h, win,
        tiered: rng() < 0.28,
        alpha: 0.7 + rng() * 0.3,
      });
    }

    this.signs = [];
    for (let i = 0; i < 11; i++) {
      const color = pick(['#ff4560', '#45f0e0', '#ffcf6b', '#ff7b9c']);
      this.signs.push({
        x: -150 + i * 330 + rng() * 150,
        y: 320 + rng() * 110,
        w: 20 + rng() * 12,
        h: 76 + rng() * 90,
        char: pick(KANJI),
        color,
        phase: rng() * TAU,
        speed: 0.7 + rng() * 2.4,
        flicker: rng() < 0.25,
      });
    }

    this.pagodas = [
      { x: 280, s: 1.15, factor: 0.16 },
      { x: 1560, s: 0.85, factor: 0.19 },
      { x: 2720, s: 1.05, factor: 0.18 },
    ];

    this.torii = [
      { x: 900, s: 1, factor: 0.27 },
      { x: 2360, s: 0.82, factor: 0.29 },
    ];

    this.bamboo = [];
    for (let i = 0; i < 46; i++) {
      const cluster = rng() < 0.5 ? 0 : 1;
      this.bamboo.push({
        x: -100 + i * 95 + rng() * 60,
        h: 200 + rng() * 260,
        w: 4 + rng() * 7,
        lean: (rng() - 0.5) * 0.12,
        phase: rng() * TAU,
        alpha: 0.25 + rng() * 0.4,
        cluster,
      });
    }

    this.strings = [
      { x: -300, y: 205, len: 1900, sag: 90, factor: 0.33, count: 12, phase: rng() * 10 },
      { x: 1450, y: 245, len: 1700, sag: 70, factor: 0.36, count: 10, phase: rng() * 10 },
    ];

    this.petals = [];
    for (let i = 0; i < 34; i++) {
      this.petals.push({
        x: Math.random() * 1600,
        y: Math.random() * 760,
        s: rand(1.5, 4),
        vy: rand(12, 34),
        phase: rand(0, TAU),
        spin: rand(-2, 2),
        rot: rand(0, TAU),
        alpha: rand(0.25, 0.7),
      });
    }

    this.rain = [];
    for (let i = 0; i < 100; i++) {
      this.rain.push({
        x: Math.random() * 1600,
        y: Math.random() * 760,
        len: rand(9, 26),
        speed: rand(680, 1100),
        alpha: rand(0.05, 0.19),
      });
    }

    this.fireflies = [];
    for (let i = 0; i < 16; i++) {
      this.fireflies.push({
        x: rand(0, WORLD_W), y: rand(GROUND_Y - 180, GROUND_Y - 10),
        phase: rand(0, TAU), speed: rand(0.5, 1.4), r: rand(0.8, 2),
      });
    }

    this.fogOffsets = [0, 0.33, 0.66];
  }

  resize(viewW, viewH, extraY) {
    this.viewW = viewW;
    this.viewH = viewH;
    this.extraY = extraY;
  }

  update(dt, camX) {
    this.time += dt;
    const w = this.viewW;
    const h = this.viewH;
    for (const p of this.petals) {
      p.y += p.vy * dt;
      p.x += Math.sin(this.time * 0.7 + p.phase) * 18 * dt + 14 * dt;
      p.rot += p.spin * dt;
      if (p.y > h + 20) { p.y = -20; p.x = Math.random() * w; }
      if (p.x > w + 30) p.x = -20;
      if (p.x < -30) p.x = w + 20;
    }
    for (const r of this.rain) {
      r.y += r.speed * dt;
      r.x += r.speed * 0.12 * dt;
      if (r.y > h + 30) { r.y = -40; r.x = Math.random() * w; }
      if (r.x > w + 20) r.x = -20;
    }
  }

  sky(ctx, danger) {
    const { viewW, viewH } = this;
    const horizon = GROUND_Y + this.extraY;
    const g = ctx.createLinearGradient(0, 0, 0, Math.max(horizon, viewH));
    const d = clamp(danger, 0, 1);
    g.addColorStop(0, d > 0.3 ? '#0b0309' : '#04050e');
    g.addColorStop(0.32, d > 0.3 ? '#1c0612' : '#080820');
    g.addColorStop(0.58, d > 0.3 ? '#330b1a' : '#151028');
    g.addColorStop(0.78, d > 0.3 ? '#4a1018' : '#2a1427');
    g.addColorStop(0.92, d > 0.3 ? '#3d0c12' : '#471a2a');
    g.addColorStop(1, '#0d0810');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, viewW, viewH);

    // aurora glow near horizon
    const hg = ctx.createLinearGradient(0, horizon - 230, 0, horizon);
    hg.addColorStop(0, 'rgba(255,70,110,0)');
    hg.addColorStop(1, d > 0.3 ? 'rgba(180,30,50,0.16)' : 'rgba(150,40,90,0.10)');
    ctx.fillStyle = hg;
    ctx.fillRect(0, horizon - 230, viewW, 230);
  }

  drawMoon(ctx, danger) {
    const horizon = GROUND_Y + this.extraY;
    const x = this.viewW * 0.76 - (this.camX || 0) * 0.012;
    const y = Math.max(110, horizon - 460);
    const d = clamp(danger, 0, 1);
    const r = 54;

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glow = 300;
    ctx.globalAlpha = 0.55 + Math.sin(this.time * 0.4) * 0.05;
    ctx.drawImage(d > 0.35 ? this.glowRed : this.glowMoon, x - glow / 2, y - glow / 2, glow, glow);
    ctx.globalAlpha = 0.5;
    ctx.drawImage(d > 0.35 ? this.glowRed : this.glowCyan, x - 180, y - 180, 360, 360);
    ctx.restore();

    // halo rings
    ctx.save();
    ctx.strokeStyle = d > 0.35 ? 'rgba(255,80,100,0.18)' : 'rgba(200,220,255,0.13)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(x, y, r + 14, 0, TAU); ctx.stroke();
    ctx.globalAlpha = 0.6;
    ctx.beginPath(); ctx.arc(x, y, r + 30, 0, TAU); ctx.stroke();
    ctx.restore();

    // moon disc
    const mg = ctx.createRadialGradient(x - 18, y - 20, 6, x, y, r);
    if (d > 0.35) {
      mg.addColorStop(0, '#ffd9c8');
      mg.addColorStop(0.55, '#ff8a7e');
      mg.addColorStop(1, '#b02438');
    } else {
      mg.addColorStop(0, '#fff8e8');
      mg.addColorStop(0.65, '#f4e7cf');
      mg.addColorStop(1, '#cfbfa8');
    }
    ctx.fillStyle = mg;
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();

    ctx.save();
    ctx.globalAlpha = 0.14;
    ctx.fillStyle = d > 0.35 ? '#7c1020' : '#8e8478';
    for (const [cx, cy, cr] of [[-18, -12, 10], [12, 14, 7], [22, -18, 5], [-4, 24, 4]]) {
      ctx.beginPath(); ctx.arc(x + cx, y + cy, cr, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  drawStars(ctx) {
    const horizon = GROUND_Y + this.extraY;
    ctx.save();
    ctx.fillStyle = '#dfe8ff';
    for (const s of this.stars) {
      const tw = 0.45 + Math.sin(this.time * s.speed + s.phase) * 0.35 + 0.2;
      ctx.globalAlpha = tw * 0.75;
      ctx.beginPath();
      ctx.arc(s.x * this.viewW, s.y * horizon, s.r, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawRidges(ctx, camX) {
    const horizon = GROUND_Y + this.extraY;
    for (const ridge of this.ridges) {
      ctx.save();
      ctx.globalAlpha = ridge.alpha;
      ctx.fillStyle = ridge.color;
      ctx.beginPath();
      const off = -camX * ridge.factor;
      ctx.moveTo(ridge.pts[0].x + off, horizon + 60);
      for (const p of ridge.pts) ctx.lineTo(p.x + off, horizon - p.y);
      ctx.lineTo(ridge.pts[ridge.pts.length - 1].x + off, horizon + 60);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  drawCity(ctx, camX, danger) {
    const horizon = GROUND_Y + this.extraY;
    const off = -camX * 0.115;
    ctx.save();
    for (const b of this.buildings) {
      const x = b.x + off;
      if (x + b.w < -80 || x > this.viewW + 80) continue;
      const top = horizon - b.h;
      ctx.globalAlpha = b.alpha;
      ctx.fillStyle = '#080713';
      ctx.fillRect(x, top, b.w, b.h + 20);
      ctx.fillStyle = '#0d0b1c';
      if (b.tiered) {
        for (let t = 0; t < 2; t++) {
          const tw = b.w * (0.5 + t * 0.22);
          const ty = top - 12 - t * 12;
          ctx.beginPath();
          ctx.moveTo(x + b.w / 2 - tw / 2, ty + 12);
          ctx.quadraticCurveTo(x + b.w / 2, ty - 8, x + b.w / 2 + tw / 2, ty + 12);
          ctx.lineTo(x + b.w / 2 + tw / 2 - 4, ty + 12);
          ctx.quadraticCurveTo(x + b.w / 2, ty + 1, x + b.w / 2 - tw / 2 + 4, ty + 12);
          ctx.closePath();
          ctx.fill();
        }
      }
      // windows
      ctx.save();
      ctx.globalAlpha = 0.55;
      for (const w of b.win) {
        ctx.fillStyle = w.warm ? 'rgba(255,186,110,0.75)' : 'rgba(92,230,220,0.5)';
        ctx.fillRect(x + 8 + w.x * (b.w - 16), top + 10 + w.y * (b.h - 20), 3, 5);
      }
      ctx.restore();
    }
    ctx.restore();
  }

  drawPagoda(ctx, x, base, s, factor, camX, danger) {
    const px = x - camX * factor;
    ctx.save();
    ctx.translate(px, base);
    ctx.scale(s, s);
    const neon = danger > 0.4 ? 'rgba(255,90,90,' : 'rgba(255,70,100,';
    ctx.fillStyle = '#070612';
    const tiers = 5;
    for (let i = 0; i < tiers; i++) {
      const y = -i * 44;
      const w = 132 - i * 20;
      // body
      ctx.fillRect(-w * 0.28, y - 40, w * 0.56, 44);
      // curved roof
      ctx.beginPath();
      ctx.moveTo(-w / 2 - 14, y - 34);
      ctx.quadraticCurveTo(-w / 2, y - 54, 0, y - 58);
      ctx.quadraticCurveTo(w / 2, y - 54, w / 2 + 14, y - 34);
      ctx.quadraticCurveTo(w / 2 - 8, y - 40, w / 2 - 16, y - 30);
      ctx.lineTo(-w / 2 + 16, y - 30);
      ctx.quadraticCurveTo(-w / 2 + 8, y - 40, -w / 2 - 14, y - 34);
      ctx.closePath();
      ctx.fill();
      // neon rim
      ctx.strokeStyle = neon + (0.18 + i * 0.02) + ')';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(-w / 2 - 14, y - 34);
      ctx.quadraticCurveTo(-w / 2, y - 54, 0, y - 58);
      ctx.quadraticCurveTo(w / 2, y - 54, w / 2 + 14, y - 34);
      ctx.stroke();
      // lit window
      if (i < 3) {
        ctx.fillStyle = 'rgba(255,170,100,0.35)';
        ctx.fillRect(-4, y - 24, 8, 10);
      }
    }
    // spire
    ctx.strokeStyle = 'rgba(180,80,100,0.5)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, -tiers * 44 - 36); ctx.lineTo(0, -tiers * 44 - 92); ctx.stroke();
    ctx.restore();
  }

  drawTorii(ctx, x, base, s, factor, camX, danger) {
    const px = x - camX * factor;
    const red = danger > 0.4 ? '#3d0a12' : '#310a14';
    const edge = danger > 0.4 ? 'rgba(255,90,90,0.55)' : 'rgba(255,60,90,0.36)';
    ctx.save();
    ctx.translate(px, base);
    ctx.scale(s, s);
    // legs
    ctx.fillStyle = red;
    ctx.fillRect(-92, -230, 20, 232);
    ctx.fillRect(72, -230, 20, 232);
    // lower beam
    ctx.fillRect(-108, -178, 216, 14);
    // top beams
    ctx.beginPath();
    ctx.moveTo(-140, -240);
    ctx.quadraticCurveTo(0, -258, 140, -240);
    ctx.lineTo(132, -222);
    ctx.quadraticCurveTo(0, -240, -132, -222);
    ctx.closePath();
    ctx.fill();
    ctx.fillRect(-104, -212, 208, 12);
    // neon rims
    ctx.strokeStyle = edge;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(-140, -240); ctx.quadraticCurveTo(0, -258, 140, -240);
    ctx.moveTo(-132, -222); ctx.quadraticCurveTo(0, -240, 132, -222);
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,190,120,0.10)';
    ctx.fillRect(-80, -166, 160, 4);
    // hanging lantern
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.5;
    ctx.drawImage(this.glowWarm, -70 - 35, -196 - 35, 70, 70);
    ctx.restore();
    ctx.restore();
  }

  drawBamboo(ctx, camX) {
    const horizon = GROUND_Y + this.extraY;
    const off = -camX * 0.4;
    ctx.save();
    ctx.lineCap = 'round';
    for (const b of this.bamboo) {
      const x = b.x + off;
      if (x < -60 || x > this.viewW + 60) continue;
      const top = horizon - b.h;
      const sway = Math.sin(this.time * 0.5 + b.phase) * 7;
      ctx.globalAlpha = b.alpha;
      const grad = ctx.createLinearGradient(x - 12, 0, x + 12, 0);
      grad.addColorStop(0, 'rgba(6,12,12,0.9)');
      grad.addColorStop(0.55, 'rgba(22,48,40,1)');
      grad.addColorStop(1, 'rgba(8,18,18,0.85)');
      ctx.strokeStyle = grad;
      ctx.lineWidth = b.w;
      ctx.beginPath();
      ctx.moveTo(x, horizon + 6);
      ctx.quadraticCurveTo(x + sway * 0.4, horizon - b.h * 0.55, x + sway, top);
      ctx.stroke();
      // nodes
      ctx.strokeStyle = 'rgba(8,16,16,0.75)';
      ctx.lineWidth = Math.max(1, b.w * 0.3);
      for (let i = 1; i < 6; i++) {
        const t = i / 6;
        const nx = x + sway * t * t;
        const ny = horizon - b.h * t;
        ctx.beginPath();
        ctx.moveTo(nx - b.w * 0.7, ny);
        ctx.lineTo(nx + b.w * 0.7, ny);
        ctx.stroke();
      }
      // leaves
      ctx.fillStyle = 'rgba(18,48,38,0.85)';
      for (let i = 0; i < 3; i++) {
        const ly = top + i * 22 + 10;
        const side = i % 2 ? 1 : -1;
        ctx.save();
        ctx.translate(x + sway * 0.9, ly);
        ctx.rotate(side * (0.7 + Math.sin(this.time + b.phase + i) * 0.1));
        ctx.beginPath();
        ctx.ellipse(side * 18, 0, 20, 3.2, 0, 0, TAU);
        ctx.fill();
        ctx.restore();
      }
    }
    ctx.restore();
  }

  drawLanterns(ctx, camX) {
    for (const str of this.strings) {
      const off = -camX * str.factor;
      const x0 = str.x + off;
      const x1 = x0 + str.len;
      if (x1 < -100 || x0 > this.viewW + 100) continue;
      const y0 = str.y;
      // rope
      ctx.save();
      ctx.strokeStyle = 'rgba(30,18,24,0.8)';
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.quadraticCurveTo((x0 + x1) / 2, y0 + str.sag * 2, x1, y0);
      ctx.stroke();
      ctx.restore();

      for (let i = 0; i < str.count; i++) {
        const t = (i + 1) / (str.count + 1);
        const x = lerp(x0, x1, t);
        const sag = 4 * t * (1 - t);
        const y = y0 + str.sag * sag * 2;
        if (x < -40 || x > this.viewW + 40) continue;
        const sway = Math.sin(this.time * 1.1 + i * 1.3 + str.phase) * 2.5;
        const sprite = this.lanternSprites[i % this.lanternSprites.length];
        ctx.save();
        ctx.translate(x + sway, y + 12);
        // glow
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = 0.38 + Math.sin(this.time * 2 + i) * 0.05;
        ctx.drawImage(this.glowWarm, -36, -42, 72, 84);
        ctx.restore();
        ctx.save();
        ctx.translate(x + sway, y + 10);
        ctx.rotate(sway * 0.012);
        ctx.drawImage(sprite, -14, -20, 28, 42);
        ctx.restore();
      }
    }
  }

  drawFireflies(ctx, camX, danger) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const f of this.fireflies) {
      const x = f.x - camX * 0.9;
      if (x < -20 || x > this.viewW + 20) continue;
      const y = f.y + Math.sin(this.time * f.speed + f.phase) * 14;
      const a = 0.3 + Math.sin(this.time * 2.4 + f.phase) * 0.25;
      ctx.globalAlpha = Math.max(0, a);
      ctx.fillStyle = danger > 0.5 ? '#ff8a7a' : '#a8ffd8';
      ctx.beginPath(); ctx.arc(x, y, f.r, 0, TAU); ctx.fill();
      ctx.globalAlpha = Math.max(0, a * 0.3);
      ctx.beginPath(); ctx.arc(x, y, f.r * 5, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  drawFog(ctx, camX) {
    const horizon = GROUND_Y + this.extraY;
    ctx.save();
    const g = ctx.createLinearGradient(0, horizon - 130, 0, horizon + 40);
    g.addColorStop(0, 'rgba(40,30,60,0)');
    g.addColorStop(0.6, 'rgba(58,42,80,0.10)');
    g.addColorStop(1, 'rgba(20,14,30,0.34)');
    ctx.fillStyle = g;
    ctx.fillRect(0, horizon - 130, this.viewW, 180);
    ctx.restore();

    ctx.save();
    for (let i = 0; i < 3; i++) {
      const off = ((this.time * (5 + i * 3) + i * 400 - camX * 0.3) % (this.viewW + 600)) - 300;
      const g2 = ctx.createRadialGradient(off, horizon - 24, 0, off, horizon - 24, 380);
      g2.addColorStop(0, 'rgba(120,110,150,0.06)');
      g2.addColorStop(1, 'rgba(120,110,150,0)');
      ctx.fillStyle = g2;
      ctx.fillRect(off - 400, horizon - 170, 800, 260);
    }
    ctx.restore();
  }

  draw(ctx, camX, danger) {
    this.camX = camX;
    this.sky(ctx, danger);
    this.drawStars(ctx);
    this.drawMoon(ctx, danger);
    this.drawRidges(ctx, camX);
    this.drawCity(ctx, camX, danger);
    for (const p of this.pagodas) {
      this.drawPagoda(ctx, p.x, GROUND_Y + this.extraY + 10, p.s, p.factor, camX, danger);
    }
    for (const t of this.torii) {
      this.drawTorii(ctx, t.x, GROUND_Y + this.extraY + 8, t.s, t.factor, camX, danger);
    }
    this.drawBamboo(ctx, camX);
    this.drawLanterns(ctx, camX);
    this.drawFireflies(ctx, camX, danger);
    this.drawFog(ctx, camX);
  }

  drawForeground(ctx, camX, danger) {
    const { viewW, viewH } = this;
    // rain
    ctx.save();
    ctx.strokeStyle = danger > 0.5 ? 'rgba(255,150,150,0.22)' : 'rgba(170,205,255,0.22)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (const r of this.rain) {
      const x = ((r.x - camX * 0.06) % (viewW + 40) + viewW + 40) % (viewW + 40) - 20;
      ctx.globalAlpha = r.alpha;
      ctx.moveTo(x, r.y);
      ctx.lineTo(x - r.len * 0.12, r.y + r.len);
    }
    ctx.stroke();
    ctx.restore();

    // petals
    ctx.save();
    for (const p of this.petals) {
      const x = ((p.x - camX * 0.14) % (viewW + 40) + viewW + 40) % (viewW + 40) - 20;
      ctx.globalAlpha = p.alpha;
      ctx.save();
      ctx.translate(x, p.y);
      ctx.rotate(p.rot);
      ctx.fillStyle = danger > 0.5 ? '#ff9a9a' : '#ffb7c9';
      ctx.beginPath();
      ctx.ellipse(0, 0, p.s, p.s * 0.42, 0, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();

    // top corner branches
    ctx.save();
    ctx.fillStyle = 'rgba(4,6,8,0.9)';
    ctx.strokeStyle = 'rgba(8,12,12,0.95)';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(-20, 20);
    ctx.quadraticCurveTo(120, 70, 230, 40);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(-10, 50);
    ctx.quadraticCurveTo(80, 100, 170, 90);
    ctx.stroke();
    ctx.restore();
  }
}

// SHADOW NINJA — player, enemies, projectiles, pickups

import {
  TAU, GROUND_Y, PLATFORMS, WORLD_W, clamp, lerp, rand, pick, sign,
  easeOutCubic, easeOutBack, dist2, circleRect,
} from './utils.js';

const GRAVITY = 2350;
const JUMP_V = -790;
const DOUBLE_JUMP_V = -715;
const MAX_SPEED = 345;

function shadowBlob(ctx, x, y, w, alpha = 0.42) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.ellipse(x, y, w, w * 0.22, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawSword(ctx, x, y, angle, len = 46, color = '#9ef7ff') {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  // handle
  ctx.strokeStyle = '#1b1420';
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-13, 0); ctx.lineTo(0, 0); ctx.stroke();
  ctx.strokeStyle = '#c83246';
  ctx.lineWidth = 2;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-11 + i * 3.4, -2.6);
    ctx.lineTo(-9 + i * 3.4, 2.6);
    ctx.stroke();
  }
  // guard
  ctx.fillStyle = '#c9a24a';
  ctx.beginPath(); ctx.ellipse(1, 0, 3, 6, 0, 0, TAU); ctx.fill();
  // blade glow
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = color;
  ctx.globalAlpha = 0.22;
  ctx.lineWidth = 8;
  ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(len, -1.5); ctx.stroke();
  // blade
  ctx.globalAlpha = 1;
  const g = ctx.createLinearGradient(4, 0, len, 0);
  g.addColorStop(0, '#dfe9f2');
  g.addColorStop(0.6, '#ffffff');
  g.addColorStop(1, '#b9d9e4');
  ctx.strokeStyle = g;
  ctx.lineWidth = 3.2;
  ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(len, -1.5); ctx.stroke();
  ctx.globalAlpha = 0.9;
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(5, -1); ctx.lineTo(len - 2, -2.2); ctx.stroke();
  ctx.restore();
}

// ----------------------------------------------------------------------------
// PLAYER
// ----------------------------------------------------------------------------
export class Player {
  constructor(game) {
    this.game = game;
    this.w = 32;
    this.h = 62;
    this.x = 400;
    this.y = GROUND_Y;
    this.vx = 0;
    this.vy = 0;
    this.facing = 1;
    this.onGround = true;
    this.prevY = this.y;
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.jumps = 0;
    this.dashTimer = 0;
    this.dashCd = 0;
    this.dashDir = 1;
    this.airDashUsed = false;
    this.invuln = 0;
    this.hitFlash = 0;
    this.attack = null;
    this.attackBuffer = 0;
    this.comboStep = 0;
    this.comboWindow = 0;
    this.health = 100;
    this.maxHealth = 100;
    this.focus = 0;
    this.maxFocus = 100;
    this.animTime = 0;
    this.airAttacks = 0;
    this.hurtLean = 0;
    this.ghostTimer = 0;
    this.dashHits = new Set();
    this.alive = true;
    this.deathTimer = 0;
  }

  get rect() {
    return { x: this.x - 16, y: this.y - 60, w: 32, h: 60 };
  }

  reset() {
    this.x = 400;
    this.y = GROUND_Y;
    this.vx = 0;
    this.vy = 0;
    this.facing = 1;
    this.health = this.maxHealth;
    this.focus = 0;
    this.invuln = 0;
    this.dashCd = 0;
    this.dashTimer = 0;
    this.attack = null;
    this.alive = true;
    this.deathTimer = 0;
    this.animTime = 0;
    this.onGround = true;
    this.hitFlash = 0;
    this.airAttacks = 0;
    this.attackBuffer = 0;
    this.comboStep = 0;
    this.comboWindow = 0;
  }

  startAttack(index, air = false) {
    const durations = [0.3, 0.31, 0.42];
    this.attack = {
      index,
      t: 0,
      duration: durations[index],
      active: false,
      hit: new Set(),
      queued: false,
      air,
      didHit: false,
    };
    this.comboStep = index;
    this.comboWindow = 0.28;
    if (index === 0) this.vx += this.facing * 190;
    else if (index === 1) this.vx += this.facing * 150;
    else this.vx += this.facing * 110;
    if (!air) this.vx = clamp(this.vx, -520, 520);
    this.game.sound.sfx(index === 2 ? 'slashHeavy' : 'slash', 1);
    const sx = this.x + this.facing * 34;
    this.game.fx.slash(
      sx, this.y - 38,
      this.facing > 0 ? -0.25 : Math.PI + 0.25,
      index === 2 ? 90 : 70,
      index === 2 ? '#ff6b81' : '#aef7ff',
      0.22,
      index === 2 ? 12 : 8,
      index === 2 ? 3.6 : 1.9,
    );
    this.game.shake(index === 2 ? 0.16 : 0.08);
  }

  attackInfo() {
    if (!this.attack || !this.attack.active) return null;
    const i = this.attack.index;
    const coffee = this.facing;
    if (i === 2) {
      return {
        x: this.x, y: this.y - 36, r: this.attack.air ? 96 : 112,
        damage: this.attack.air ? 20 : 28, knock: 340, index: i, air: this.attack.air,
      };
    }
    return {
      x: this.x + coffee * 58, y: this.y - 36, r: i === 1 ? 74 : 70,
      damage: i === 1 ? 16 : 14, knock: i === 1 ? 260 : 220, index: i, air: this.attack.air,
    };
  }

  update(dt, input) {
    this.animTime += dt;
    const game = this.game;
    if (!this.alive) {
      this.deathTimer += dt;
      this.vy += GRAVITY * dt;
      this.y = Math.min(GROUND_Y, this.y + this.vy * dt);
      this.vx *= Math.exp(-3 * dt);
      this.x += this.vx * dt;
      return;
    }

    this.prevY = this.y;
    const move = input.moveX();
    const wasGround = this.onGround;

    this.dashCd = Math.max(0, this.dashCd - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.hurtLean = lerp(this.hurtLean, 0, Math.min(1, dt * 8));
    this.attackBuffer = Math.max(0, this.attackBuffer - dt);
    this.comboWindow = Math.max(0, this.comboWindow - dt);
    this.coyote = this.onGround ? 0.1 : Math.max(0, this.coyote - dt);
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);

    // ---- dash ----
    if (input.pressed('dash') && this.dashCd <= 0 && this.dashTimer <= 0) {
      if (this.onGround || !this.airDashUsed) {
        this.dashTimer = 0.17;
        this.dashCd = 0.62;
        this.dashDir = move !== 0 ? sign(move) : this.facing;
        this.facing = this.dashDir;
        this.invuln = Math.max(this.invuln, 0.24);
        this.vy = 0;
        this.dashHits.clear();
        if (!this.onGround) this.airDashUsed = true;
        this.game.sound.sfx('dash');
        this.game.fx.ring(this.x, this.y - 34, 'rgba(110,240,255,0.8)', 70, 3, 0.3, 8);
        this.game.shake(0.1);
        this.game.dustBurst(this.x, this.y, -this.dashDir, 7);
      }
    }

    // ---- attack input ----
    if (input.pressed('attack')) {
      if (!this.attack && this.dashTimer <= 0) {
        if (this.onGround) {
          const next = this.comboWindow > 0 ? (this.comboStep + 1) % 3 : 0;
          this.startAttack(next, false);
        } else if (this.airAttacks < 2) {
          this.airAttacks++;
          this.startAttack(2, true);
        }
      } else if (this.attack) {
        this.attack.queued = true;
      }
    }

    // ---- burst ----
    if (input.pressed('burst') && this.focus >= this.maxFocus) {
      this.focus = 0;
      this.invuln = Math.max(this.invuln, 1.05);
      this.dashCd = 0;
      game.triggerBurst(this);
    }

    // ---- horizontal movement ----
    if (this.dashTimer > 0) {
      this.dashTimer -= dt;
      this.vx = this.dashDir * 760;
      this.vy = 0;
      this.ghostTimer -= dt;
      if (this.ghostTimer <= 0) {
        this.ghostTimer = 0.035;
        game.fx.ghost(this.x, this.y, this.facing, '95,235,255', 0.26, 1);
      }
      if (this.dashTimer <= 0) this.vx = this.dashDir * 330;
    } else {
      const attacking = !!this.attack;
      const control = attacking ? 0.5 : 1;
      if (move !== 0) {
        const target = move * MAX_SPEED;
        this.vx += (target - this.vx) * Math.min(1, dt * (this.onGround ? 12 : 8) * control);
        if (!attacking) this.facing = sign(move);
      } else {
        const friction = this.onGround ? 9 : 1.6;
        this.vx *= Math.exp(-friction * dt);
      }
      this.vx = clamp(this.vx, -MAX_SPEED * 1.4, MAX_SPEED * 1.4);
    }

    // ---- jump ----
    if (input.pressed('jump')) this.jumpBuffer = 0.12;
    if (this.jumpBuffer > 0 && this.dashTimer <= 0) {
      if (this.coyote > 0) {
        this.vy = JUMP_V;
        this.onGround = false;
        this.coyote = 0;
        this.jumpBuffer = 0;
        this.jumps = 1;
        this.airAttacks = 0;
        game.sound.sfx('jump');
        game.fx.dust(this.x, this.y, 0, 4);
        game.fx.ring(this.x, this.y - 4, 'rgba(180,220,255,0.35)', 26, 2, 0.25, 4);
      } else if (this.jumps < 2) {
        this.vy = DOUBLE_JUMP_V;
        this.jumps = 2;
        this.jumpBuffer = 0;
        this.airAttacks = 0;
        game.sound.sfx('doubleJump');
        game.fx.ring(this.x, this.y - 26, 'rgba(120,240,255,0.85)', 46, 2.5, 0.32, 6);
        for (let i = 0; i < 8; i++) {
          game.fx.particles.push({
            type: 'spark', x: this.x, y: this.y - 20,
            vx: Math.cos((i / 8) * TAU) * rand(60, 160),
            vy: Math.sin((i / 8) * TAU) * rand(60, 160),
            life: 0.35, max: 0.35, size: 2, color: '#9ef7ff',
            drag: 4, grav: 120, glow: true,
          });
        }
      }
    }
    if (!input.down('jump') && this.vy < -220) this.vy += 1900 * dt;

    // ---- attack progression ----
    if (this.attack) {
      const a = this.attack;
      a.t += dt;
      const i = a.index;
      const activeStart = i === 2 ? (a.air ? 0.07 : 0.08) : 0.055;
      const activeEnd = i === 2 ? (a.air ? 0.25 : 0.27) : 0.16;
      a.active = a.t >= activeStart && a.t <= activeEnd;
      if (a.active) {
        const info = this.attackInfo();
        if (info) game.resolvePlayerAttack(this, info);
      }
      if (a.t >= a.duration * 0.62 && a.queued) {
        const next = (i + 1) % 3;
        const wasAir = a.air;
        this.attack = null;
        if (wasAir && this.onGround) this.startAttack(0, false);
        else this.startAttack(next, wasAir);
      } else if (a.t >= a.duration) {
        this.attack = null;
        this.comboWindow = 0.22;
      }
    }

    // ---- physics ----
    if (this.dashTimer <= 0) this.vy += GRAVITY * dt;
    this.vy = Math.min(this.vy, 1300);
    this.x += this.vx * dt;
    this.y += this.vy * dt;

    // world bounds
    if (this.x < 34) { this.x = 34; this.vx = Math.max(0, this.vx); }
    if (this.x > WORLD_W - 34) { this.x = WORLD_W - 34; this.vx = Math.min(0, this.vx); }

    // ground / platforms
    this.onGround = false;
    const wasFalling = this.vy >= 0;
    if (this.y >= GROUND_Y) {
      if (!wasGround && this.vy > 300) {
        game.fx.dust(this.x, this.y, 0, 5);
        game.shake(0.06);
      }
      this.y = GROUND_Y;
      this.vy = 0;
      this.onGround = true;
    }
    if (wasFalling && this.vy > 0 && this.dashTimer <= 0) {
      for (const p of PLATFORMS) {
        if (
          this.x > p.x - 10 && this.x < p.x + p.w + 10 &&
          this.prevY <= p.y + 1 && this.y >= p.y
        ) {
          this.y = p.y;
          this.vy = 0;
          this.onGround = true;
          if (!wasGround) {
            game.fx.dust(this.x, this.y, 0, 3);
            game.fx.ring(this.x, this.y, 'rgba(160,220,255,0.3)', 22, 2, 0.2, 3);
          }
          break;
        }
      }
    }
    if (this.onGround) {
      this.jumps = 0;
      this.airDashUsed = false;
      this.airAttacks = 0;
    }

    // dash trail + contact damage
    if (this.dashTimer > 0) {
      game.resolveDashAttack(this);
    }

    // footsteps
    if (this.onGround && Math.abs(this.vx) > 100 && this.dashTimer <= 0) {
      this.stepTimer = (this.stepTimer || 0) - dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = 0.12;
        game.fx.dust(this.x - this.facing * 8, this.y, -this.facing, 1);
      }
    }

    if (this.y > 900) { this.y = GROUND_Y; this.vy = 0; }
  }

  takeDamage(amount, dir) {
    if (!this.alive || this.invuln > 0 || this.dashTimer > 0) return false;
    this.health = Math.max(0, this.health - amount);
    this.invuln = 1.0;
    this.hitFlash = 0.2;
    this.hurtLean = 1;
    this.vx = dir * 420;
    this.vy = -280;
    this.onGround = false;
    this.game.onPlayerHit(amount, dir);
    if (this.health <= 0) {
      this.alive = false;
      this.deathTimer = 0;
      this.vy = -420;
      this.game.onPlayerDeath();
    }
    return true;
  }

  heal(v) {
    this.health = Math.min(this.maxHealth, this.health + v);
  }

  addFocus(v) {
    this.focus = Math.min(this.maxFocus, this.focus + v);
  }

  draw(ctx) {
    const t = this.animTime;
    const blink = this.invuln > 0 && this.dashTimer <= 0 && this.hitFlash <= 0 && this.alive
      ? 0.55 + Math.sin(this.animTime * 48) * 0.35
      : 1;
    ctx.save();
    if (!this.alive) {
      const fall = Math.min(1, this.deathTimer * 1.6);
      ctx.globalAlpha = Math.max(0, 1 - this.deathTimer * 0.7);
      ctx.translate(this.x, this.y);
      ctx.rotate(-this.facing * fall * 1.2);
      ctx.translate(0, 0);
      ctx.scale(this.facing, 1);
      drawNinjaBody(ctx, this, t, null);
      ctx.restore();
      return;
    }
    ctx.globalAlpha = blink;
    if (this.hitFlash > 0) ctx.filter = 'brightness(2.6) saturate(0.4)';
    drawNinjaBody(ctx, this, t, this.attack);
    ctx.restore();
    if (this.hitFlash > 0) ctx.filter = 'none';
  }
}

function drawNinjaBody(ctx, p, t, attack) {
  const moving = Math.abs(p.vx) > 60;
  const run = p.onGround ? clamp(Math.abs(p.vx) / 340, 0, 1) : 0;
  const phase = t * (7 + run * 8);
  const bob = p.onGround ? Math.sin(phase * 2) * (1 + run) : 0;
  const airborne = !p.onGround && p.dashTimer <= 0;
  const dashing = p.dashTimer > 0;

  ctx.save();
  ctx.translate(p.x, p.y);
  // shadow
  const air = clamp((GROUND_Y - p.y) / 260, 0, 1);
  shadowBlob(ctx, 0, 1, 22 * (1 - air * 0.45), 0.36 * (1 - air * 0.5));

  ctx.scale(p.facing, 1);
  if (p.hurtLean > 0) ctx.rotate(-p.hurtLean * 0.22);
  if (dashing) ctx.rotate(-0.22);
  ctx.translate(0, bob);

  // attack angle
  let swordAngle = -2.35 - Math.sin(t * 2) * 0.04;
  let armAngle = swordAngle;
  if (dashing) { swordAngle = -0.15; armAngle = 0.2; }
  else if (airborne) { swordAngle = 1.9; armAngle = 1.7; }
  else if (moving) { swordAngle = -2.5; armAngle = -2.2; }
  if (attack) {
    const prog = clamp(attack.t / attack.duration, 0, 1);
    if (attack.index === 0) {
      swordAngle = lerp(-2.0, 0.75, easeOutCubic(clamp(prog * 1.9, 0, 1)));
      armAngle = swordAngle;
    } else if (attack.index === 1) {
      swordAngle = lerp(1.05, -1.9, easeOutCubic(clamp(prog * 1.9, 0, 1)));
      armAngle = swordAngle;
    } else {
      swordAngle = -0.3 + prog * TAU * 1.15;
      armAngle = -0.5 + prog * TAU * 0.9;
    }
  }

  const stride = Math.sin(phase) * 10 * run;
  const stride2 = Math.sin(phase + Math.PI) * 10 * run;

  // scarf
  const speed = clamp(Math.abs(p.vx) / 340, 0, 1);
  const scarfLen = 38 + speed * 34 + (dashing ? 34 : 0);
  const scarfWave = Math.sin(t * 6.5) * 6;
  ctx.save();
  ctx.globalAlpha = 0.92;
  for (let layer = 0; layer < 2; layer++) {
    const g = ctx.createLinearGradient(0, 0, -scarfLen, -30);
    g.addColorStop(0, layer === 0 ? '#c8102e' : '#7e0b1d');
    g.addColorStop(1, layer === 0 ? '#ff4d5e' : '#a3122a');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-3, -63 + layer * 3);
    ctx.bezierCurveTo(
      -18, -66 + layer * 5,
      -scarfLen * 0.55, -48 + scarfWave + layer * 4,
      -scarfLen, -58 + Math.sin(t * 5 + layer) * 10 + layer * 4,
    );
    ctx.bezierCurveTo(
      -scarfLen * 0.6, -38 + scarfWave + layer * 4,
      -16, -52 + layer * 5, -3, -56 + layer * 3,
    );
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  const legColor = '#0c1424';
  const rim = 'rgba(126,239,255,0.5)';

  // back arm
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#0a111f';
  ctx.lineWidth = 8;
  const backSwing = moving ? Math.sin(phase + Math.PI) * 6 : 0;
  ctx.beginPath();
  ctx.moveTo(-5, -55);
  ctx.quadraticCurveTo(-14, -46 + backSwing, -12 - (dashing ? 14 : 0), -34 + backSwing);
  ctx.stroke();

  // back leg
  ctx.strokeStyle = legColor;
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(-4, -36);
  if (airborne || dashing) {
    ctx.quadraticCurveTo(-14, -26, -22, -16);
  } else {
    ctx.quadraticCurveTo(-7 + stride2 * 0.7, -20, -10 + stride2, -2);
  }
  ctx.stroke();
  ctx.strokeStyle = '#1a2336';
  ctx.lineWidth = 7;
  ctx.beginPath();
  if (airborne || dashing) {
    ctx.moveTo(-22, -16); ctx.lineTo(-28, -8);
  } else {
    ctx.moveTo(-10 + stride2, -5); ctx.lineTo(-10 + stride2 + 5, -2);
  }
  ctx.stroke();

  // torso
  const g = ctx.createLinearGradient(-16, -66, 12, -34);
  g.addColorStop(0, '#070d18');
  g.addColorStop(0.5, '#111d30');
  g.addColorStop(1, '#1c3048');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-10, -38);
  ctx.quadraticCurveTo(-14, -56, -8, -65);
  ctx.quadraticCurveTo(3, -70, 10, -62);
  ctx.quadraticCurveTo(13, -52, 7, -37);
  ctx.quadraticCurveTo(-2, -32, -10, -38);
  ctx.closePath();
  ctx.fill();
  // rim light
  ctx.strokeStyle = rim;
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(9, -61);
  ctx.quadraticCurveTo(13, -51, 7, -38);
  ctx.stroke();

  // chest wrap
  ctx.strokeStyle = '#9c1830';
  ctx.lineWidth = 4.5;
  ctx.beginPath();
  ctx.moveTo(-8, -57);
  ctx.lineTo(8, -47);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,110,120,0.45)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-8, -58.5); ctx.lineTo(7, -49); ctx.stroke();

  // belt + knot
  ctx.fillStyle = '#17111a';
  ctx.fillRect(-9, -41, 18, 5);
  ctx.fillStyle = '#d8a94b';
  ctx.beginPath(); ctx.arc(6, -39, 3.2, 0, TAU); ctx.fill();
  ctx.strokeStyle = '#d8a94b';
  ctx.lineWidth = 1.2;
  ctx.beginPath(); ctx.moveTo(6, -37); ctx.lineTo(8, -28); ctx.stroke();

  // front leg
  ctx.strokeStyle = legColor;
  ctx.lineWidth = 11;
  ctx.beginPath();
  ctx.moveTo(3, -37);
  if (airborne || dashing) {
    ctx.quadraticCurveTo(10, -26, 20, -22);
  } else {
    ctx.quadraticCurveTo(5 - stride * 0.6, -20, 8 - stride, -2);
  }
  ctx.stroke();
  ctx.strokeStyle = '#20304a';
  ctx.lineWidth = 8;
  ctx.beginPath();
  if (airborne || dashing) {
    ctx.moveTo(20, -22); ctx.lineTo(27, -16);
  } else {
    ctx.moveTo(8 - stride, -6); ctx.lineTo(8 - stride + 5, -2);
  }
  ctx.stroke();
  // shin glow
  ctx.strokeStyle = 'rgba(80,210,230,0.35)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  if (!airborne && !dashing) {
    ctx.moveTo(6 - stride * 0.5, -18);
    ctx.lineTo(8 - stride, -6);
  }
  ctx.stroke();

  // head
  ctx.save();
  // hood tail
  ctx.fillStyle = '#0b1424';
  ctx.beginPath();
  ctx.moveTo(-4, -70);
  ctx.quadraticCurveTo(-18, -71, -22, -62);
  ctx.quadraticCurveTo(-12, -64, -6, -63);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#101b2b';
  ctx.beginPath();
  ctx.ellipse(2, -67, 10.5, 11, 0.06, 0, TAU);
  ctx.fill();
  // face mask
  ctx.fillStyle = '#080d16';
  ctx.beginPath();
  ctx.ellipse(6, -64, 8.5, 8, 0.1, 0, TAU);
  ctx.fill();
  // eyes
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = '#7df7ff';
  ctx.globalAlpha = 0.9;
  ctx.beginPath();
  ctx.ellipse(7.5, -68, 2.8, 1.25, -0.12, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = 0.28;
  ctx.beginPath(); ctx.arc(8, -68, 5.5, 0, TAU); ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;
  // headband
  ctx.strokeStyle = '#b81633';
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.moveTo(-7, -72);
  ctx.quadraticCurveTo(-16, -70, -24 - speed * 10, -66 + Math.sin(t * 8) * 3);
  ctx.stroke();
  ctx.restore();

  // sword arm
  const shoulderX = 4, shoulderY = -55;
  const handX = shoulderX + Math.cos(armAngle) * 17;
  const handY = shoulderY + Math.sin(armAngle) * 17;
  ctx.strokeStyle = '#101a2a';
  ctx.lineWidth = 7.5;
  ctx.beginPath();
  ctx.moveTo(shoulderX, shoulderY);
  ctx.quadraticCurveTo(shoulderX + Math.cos(armAngle) * 10 + 3, shoulderY + Math.sin(armAngle) * 10 - 3, handX, handY);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(120,230,255,0.28)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(shoulderX + 2, shoulderY + 2);
  ctx.lineTo(handX + 1, handY - 1);
  ctx.stroke();

  drawSword(ctx, handX, handY, swordAngle, 48 + (attack && attack.index === 2 ? 8 : 0));

  // glow at eye level
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.16;
  ctx.fillStyle = '#7df7ff';
  ctx.beginPath(); ctx.arc(6, -68, 13, 0, TAU); ctx.fill();
  ctx.restore();

  ctx.restore();
}

// ----------------------------------------------------------------------------
// ENEMIES
// ----------------------------------------------------------------------------
const ENEMY_STATS = {
  ronin: { hp: 55, speed: 132, w: 34, h: 64, damage: 12, score: 120 },
  archer: { hp: 42, speed: 96, w: 30, h: 60, damage: 9, score: 150 },
  brute: { hp: 170, speed: 62, w: 54, h: 94, damage: 22, score: 300 },
};

let enemyId = 1;

export class Enemy {
  constructor(type, x, y, game, wave) {
    const s = ENEMY_STATS[type];
    this.id = enemyId++;
    this.type = type;
    this.game = game;
    this.w = s.w;
    this.h = s.h;
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.facing = 1;
    this.maxHp = Math.round(s.hp * (1 + 0.16 * Math.max(0, wave - 1)));
    this.hp = this.maxHp;
    this.speed = s.speed * (1 + 0.035 * Math.max(0, wave - 1));
    this.damage = Math.round(s.damage * (1 + 0.075 * Math.max(0, wave - 1)));
    this.scoreValue = s.score;
    this.state = 'spawn';
    this.timer = 0.55;
    this.cooldown = rand(0.4, 1.1);
    this.hitFlash = 0;
    this.windup = 0;
    this.attackT = 0;
    this.didHit = false;
    this.dead = false;
    this.deathTimer = 0;
    this.anim = rand(0, 10);
    this.stateTime = 0;
    this.blockShake = 0;
    this.arrowCharged = false;
    this.telegraph = 0;
  }

  get rect() {
    return { x: this.x - this.w / 2, y: this.y - this.h, w: this.w, h: this.h };
  }

  get alive() {
    return !this.dead;
  }

  update(dt, game) {
    this.anim += dt;
    this.stateTime += dt;
    if (this.dead) {
      this.deathTimer -= dt;
      this.vx *= Math.exp(-4 * dt);
      this.x += this.vx * dt;
      return;
    }
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.telegraph = Math.max(0, this.telegraph - dt);
    const player = game.player;
    const dx = player.x - this.x;
    const adx = Math.abs(dx);
    const dir = sign(dx || 1);
    if (this.state !== 'attack' && this.state !== 'windup') this.facing = dir;
    this.vy += GRAVITY * dt;
    this.y = Math.min(GROUND_Y, this.y + this.vy * dt);
    if (this.y >= GROUND_Y) { this.y = GROUND_Y; this.vy = 0; }

    // separation from other enemies
    for (const e of game.enemies) {
      if (e === this || e.dead || e.type === 'boss') continue;
      const d = this.x - e.x;
      if (Math.abs(d) < (this.w + e.w) * 0.42 && Math.abs(this.y - e.y) < 20) {
        this.x += sign(d || 1) * 26 * dt;
      }
    }

    switch (this.type) {
      case 'ronin': this.updateRonin(dt, game, player, dx, adx, dir); break;
      case 'archer': this.updateArcher(dt, game, player, dx, adx, dir); break;
      case 'brute': this.updateBrute(dt, game, player, dx, adx, dir); break;
    }

    this.x += this.vx * dt;
    this.x = clamp(this.x, 30, WORLD_W - 30);
    if (this.y > 900) this.dead = true;
  }

  moveToward(speed, dir, dt, game) {
    this.vx = lerp(this.vx, dir * speed, Math.min(1, dt * 8));
    if (Math.abs(this.vx) > 40 && Math.random() < dt * 3) game.fx.dust(this.x, this.y, -sign(this.vx), 1);
  }

  updateRonin(dt, game, player, dx, adx, dir) {
    if (this.state === 'spawn') {
      this.timer -= dt;
      this.vx = 0;
      if (this.timer <= 0) { this.state = 'chase'; this.stateTime = 0; }
      return;
    }
    if (this.state === 'chase') {
      if (adx > 82) this.moveToward(this.speed, dir, dt, game);
      else this.vx *= Math.exp(-10 * dt);
      if (adx < 112 && this.cooldown <= 0 && Math.abs(player.y - this.y) < 80) {
        this.state = 'windup';
        this.timer = 0.4;
        this.stateTime = 0;
        this.windup = 0.4;
        this.telegraph = 0.4;
        this.vx = 0;
        game.sound.sfx('click', 1);
      }
    } else if (this.state === 'windup') {
      this.timer -= dt;
      this.vx *= Math.exp(-12 * dt);
      if (this.timer <= 0) {
        this.state = 'attack';
        this.timer = 0.26;
        this.attackT = 0;
        this.didHit = false;
        this.vx = dir * 480;
        game.sound.sfx('slash', 0.7);
        game.fx.slash(this.x + dir * 42, this.y - 34, dir > 0 ? 0.15 : Math.PI - 0.15, 56, 'rgba(255,80,90,0.8)', 0.16, 6, 1.7);
      }
    } else if (this.state === 'attack') {
      this.timer -= dt;
      this.attackT += dt;
      this.vx *= Math.exp(-2.5 * dt);
      if (!this.didHit && this.attackT > 0.04) {
        const hit = { x: this.x + this.facing * 42, y: this.y - 34, r: 46 };
        if (circleRect(hit.x, hit.y, hit.r, player.rect) && player.takeDamage(this.damage, this.facing)) {
          this.didHit = true;
          game.fx.spark(hit.x, hit.y, '#ff7080', 8, 280);
        }
      }
      if (this.timer <= 0) {
        this.state = 'recover';
        this.timer = 0.42;
        this.cooldown = rand(0.85, 1.5);
      }
    } else if (this.state === 'recover') {
      this.timer -= dt;
      this.vx *= Math.exp(-8 * dt);
      if (this.timer <= 0) this.state = 'chase';
    }
  }

  updateArcher(dt, game, player, dx, adx, dir) {
    if (this.state === 'spawn') {
      this.timer -= dt;
      this.vx = 0;
      if (this.timer <= 0) this.state = 'chase';
      return;
    }
    if (this.state === 'chase') {
      if (adx < 210) this.moveToward(this.speed * 1.15, -dir, dt, game);
      else if (adx > 400) this.moveToward(this.speed * 0.8, dir, dt, game);
      else this.vx *= Math.exp(-8 * dt);
      if (this.cooldown <= 0 && adx < 620 && adx > 70) {
        this.state = 'aim';
        this.timer = 0.62;
        this.vx = 0;
        this.telegraph = 0.62;
        this.arrowCharged = false;
      }
      if (adx < 75) {
        this.vx = -dir * 340;
      }
    } else if (this.state === 'aim') {
      this.timer -= dt;
      this.vx *= Math.exp(-12 * dt);
      if (!this.arrowCharged && this.timer < 0.16) {
        this.arrowCharged = true;
        game.sound.sfx('click');
      }
      if (this.timer <= 0) {
        this.state = 'shoot';
        this.timer = 0.16;
        const tx = player.x + player.vx * 0.12;
        const ty = player.y - 30;
        const ang = Math.atan2(ty - (this.y - 34), tx - this.x);
        const sp = 640;
        game.spawnEnemyProjectile({
          type: 'arrow', x: this.x + Math.cos(ang) * 24, y: this.y - 34 + Math.sin(ang) * 24,
          vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp,
          r: 5, damage: this.damage, life: 2.2, color: '#ff9b6a',
        });
        if (this.maxHp > 60) {
          const a2 = ang + 0.12;
          game.spawnEnemyProjectile({
            type: 'arrow', x: this.x + Math.cos(a2) * 24, y: this.y - 34 + Math.sin(a2) * 24,
            vx: Math.cos(a2) * sp, vy: Math.sin(a2) * sp,
            r: 5, damage: this.damage, life: 2.2, color: '#ff9b6a',
          });
        }
        game.sound.sfx('arrow');
      }
    } else if (this.state === 'shoot') {
      this.timer -= dt;
      if (this.timer <= 0) {
        this.state = 'chase';
        this.cooldown = rand(1.8, 2.6);
      }
    }
  }

  updateBrute(dt, game, player, dx, adx, dir) {
    if (this.state === 'spawn') {
      this.timer -= dt;
      this.vx = 0;
      if (this.timer <= 0) this.state = 'chase';
      return;
    }
    if (this.state === 'chase') {
      if (adx > 105) this.moveToward(this.speed, dir, dt, game);
      else this.vx *= Math.exp(-8 * dt);
      if (adx < 150 && this.cooldown <= 0) {
        this.state = 'windup';
        this.timer = 0.68;
        this.windup = 0.68;
        this.telegraph = 0.68;
        this.vx = 0;
        this.didHit = false;
        game.sound.sfx('click');
      }
    } else if (this.state === 'windup') {
      this.timer -= dt;
      this.vx *= Math.exp(-12 * dt);
      if (this.timer <= 0) {
        this.state = 'attack';
        this.timer = 0.36;
        this.attackT = 0;
        this.didHit = false;
        game.shake(0.42);
        game.sound.sfx('slam');
        game.fx.ring(this.x + this.facing * 60, this.y, 'rgba(255,90,70,0.9)', 130, 5, 0.38, 10);
        game.fx.shards(this.x + this.facing * 64, this.y - 6, '#ff7f5a', 9, 340);
        game.fx.smoke(this.x + this.facing * 70, this.y, '90,70,80', 6, 22);
        if (Math.abs(player.x - (this.x + this.facing * 60)) < 135 && player.y > this.y - 110) {
          player.takeDamage(this.damage, this.facing);
        }
        game.spawnEnemyProjectile({
          type: 'shock', x: this.x, y: GROUND_Y, vx: this.facing * 520, vy: 0,
          r: 26, damage: Math.round(this.damage * 0.8), life: 1.4, color: '#ff6a55',
        });
        if (this.maxHp > 200) game.spawnEnemyProjectile({
          type: 'shock', x: this.x, y: GROUND_Y, vx: -this.facing * 520, vy: 0,
          r: 26, damage: Math.round(this.damage * 0.8), life: 1.4, color: '#ff6a55',
        });
      }
    } else if (this.state === 'attack') {
      this.timer -= dt;
      this.vx *= Math.exp(-10 * dt);
      if (this.timer <= 0) {
        this.state = 'recover';
        this.timer = 0.85;
        this.cooldown = rand(1.4, 2.1);
      }
    } else if (this.state === 'recover') {
      this.timer -= dt;
      this.vx *= Math.exp(-8 * dt);
      if (this.timer <= 0) this.state = 'chase';
    }
  }

  takeDamage(dmg, dir, game, opts = {}) {
    if (this.dead) return false;
    this.hp -= dmg;
    this.hitFlash = 0.14;
    if (this.type === 'brute') {
      this.vx += dir * 40;
      this.x += dir * 4;
    } else {
      this.vx += dir * (opts.knock ?? 260) * 0.6;
      this.x += dir * 5;
      if (this.state === 'windup' || this.state === 'aim') {
        this.state = 'recover';
        this.timer = 0.25;
      }
    }
    game.fx.ember(this.x, this.y - this.h * 0.6, '#ff9a86', 4, 150);
    if (this.hp <= 0) {
      this.die(game, dir);
    }
    return true;
  }

  die(game, dir) {
    this.dead = true;
    this.deathTimer = 0.55;
    this.vx = dir * 180;
    game.onEnemyKilled(this);
    const cy = this.y - this.h * 0.55;
    const color = this.type === 'brute' ? '#ff8b5c' : this.type === 'archer' ? '#7ef0d8' : '#ff5c6e';
    game.fx.ember(this.x, cy, color, 18, 260, 1.3);
    game.fx.spark(this.x, cy, '#ffe6c0', 12, 320);
    game.fx.smoke(this.x, cy, '80,60,80', 5, 20);
    game.fx.petals(this.x, cy, 5);
    game.fx.shards(this.x, cy, '#3a2028', 5, 260);
    game.shake(0.2);
    game.hitstop(0.045);
    game.sound.sfx('kill');
    if (this.type === 'brute') {
      game.fx.ring(this.x, this.y - 50, 'rgba(255,120,80,0.8)', 100, 4, 0.45);
    }
  }

  draw(ctx) {
    const alpha = this.dead ? clamp(this.deathTimer / 0.55, 0, 1) : 1;
    if (alpha <= 0) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(this.x, this.y);
    const air = clamp((GROUND_Y - this.y) / 220, 0, 1);
    shadowBlob(ctx, 0, 1, this.w * 0.62 * (1 - air * 0.4), 0.35);
    if (this.hitFlash > 0) ctx.filter = 'brightness(2.7) saturate(0.3)';
    if (this.dead) {
      ctx.rotate(this.facing * (1 - alpha) * 0.9);
      ctx.translate(0, (1 - alpha) * 10);
      ctx.globalAlpha = alpha * 0.8;
    }
    if (this.state === 'spawn') {
      const t = 1 - clamp(this.timer / 0.55, 0, 1);
      ctx.globalAlpha *= t;
      ctx.scale(0.85 + t * 0.15, 0.85 + t * 0.15);
      ctx.translate(0, (1 - t) * 18);
    }
    ctx.scale(this.facing, 1);
    if (this.type === 'ronin') drawRonin(ctx, this);
    else if (this.type === 'archer') drawArcher(ctx, this);
    else drawBrute(ctx, this);
    ctx.filter = 'none';
    ctx.restore();

    if (!this.dead && this.type === 'brute' && this.hp < this.maxHp) {
      const w = 54;
      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.55)';
      ctx.fillRect(this.x - w / 2, this.y - this.h - 16, w, 5);
      ctx.fillStyle = '#ff5f62';
      ctx.fillRect(this.x - w / 2, this.y - this.h - 16, (this.hp / this.maxHp) * w, 5);
      ctx.restore();
    }

    if (this.telegraph > 0 && !this.dead) {
      const p = 1 - this.telegraph / Math.max(0.001, this.windup || 0.62);
      ctx.save();
      ctx.translate(this.x + this.facing * (this.type === 'brute' ? 60 : 36), this.y - this.h * 0.5);
      ctx.scale(this.facing, 1);
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.35 + Math.sin(p * 24) * 0.2;
      ctx.strokeStyle = '#ff4d5e';
      ctx.lineWidth = 2;
      const r = 30 + p * 26;
      ctx.beginPath();
      ctx.arc(0, 0, r, -0.9, 0.9);
      ctx.stroke();
      ctx.fillStyle = '#ff4d5e';
      ctx.font = 'bold 22px Georgia, serif';
      ctx.textAlign = 'center';
      ctx.globalAlpha = 0.8;
      ctx.fillText('!', 0, -r - 8);
      ctx.restore();
    }
  }
}

function drawRonin(ctx, e) {
  const t = e.anim;
  const walking = Math.abs(e.vx) > 20;
  const phase = t * (walking ? 9 : 3);
  const bob = walking ? Math.sin(phase * 2) * 1.4 : Math.sin(t * 2) * 0.8;
  const wind = e.state === 'windup' ? 1 - e.timer / 0.4 : 0;
  const attack = e.state === 'attack' ? 1 - e.timer / 0.26 : 0;
  ctx.translate(0, bob);

  // legs
  const stride = walking ? Math.sin(phase) * 8 : 0;
  ctx.strokeStyle = '#0b0d17';
  ctx.lineWidth = 9;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-3, -30); ctx.lineTo(-8 + stride, -2);
  ctx.moveTo(3, -30); ctx.lineTo(8 - stride, -2);
  ctx.stroke();
  ctx.strokeStyle = '#241720';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-8 + stride - 3, -2); ctx.lineTo(-4 + stride, -2);
  ctx.moveTo(8 - stride - 3, -2); ctx.lineTo(12 - stride, -2);
  ctx.stroke();

  // tattered skirt
  ctx.fillStyle = '#170d16';
  ctx.beginPath();
  ctx.moveTo(-12, -36);
  ctx.lineTo(12, -36);
  ctx.lineTo(10, -22);
  ctx.lineTo(5, -27);
  ctx.lineTo(1, -19);
  ctx.lineTo(-4, -26);
  ctx.lineTo(-10, -20);
  ctx.closePath();
  ctx.fill();

  // torso armor
  const g = ctx.createLinearGradient(-14, -62, 14, -30);
  g.addColorStop(0, '#0a0a13');
  g.addColorStop(0.55, '#1b1420');
  g.addColorStop(1, '#2b1a24');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-12, -36);
  ctx.quadraticCurveTo(-15, -55, -7, -61);
  ctx.lineTo(8, -61);
  ctx.quadraticCurveTo(15, -54, 11, -36);
  ctx.closePath();
  ctx.fill();
  // lamellar lines
  ctx.strokeStyle = 'rgba(180,80,90,0.22)';
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-10 + i, -46 - i * 5);
    ctx.lineTo(10 - i, -46 - i * 5);
    ctx.stroke();
  }
  // red sash
  ctx.fillStyle = '#8e1424';
  ctx.fillRect(-11, -38, 22, 4);
  // shoulder plates
  ctx.fillStyle = '#14101c';
  ctx.beginPath();
  ctx.ellipse(-12, -57, 8, 6, -0.3, 0, TAU);
  ctx.ellipse(12, -57, 8, 6, 0.3, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,80,90,0.35)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.ellipse(12, -57, 8, 6, 0.3, 0, TAU); ctx.stroke();

  // head + horned helmet
  ctx.fillStyle = '#17121d';
  ctx.beginPath();
  ctx.ellipse(1, -68, 9.5, 9, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#0a0910';
  ctx.beginPath();
  ctx.moveTo(-9, -72);
  ctx.quadraticCurveTo(0, -84, 10, -72);
  ctx.lineTo(8, -68);
  ctx.quadraticCurveTo(0, -75, -8, -68);
  ctx.closePath();
  ctx.fill();
  // horns
  ctx.strokeStyle = '#b9a98e';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.moveTo(-6, -76); ctx.quadraticCurveTo(-15, -88, -12, -93);
  ctx.moveTo(7, -76); ctx.quadraticCurveTo(15, -88, 12, -93);
  ctx.stroke();
  // mask/eyes
  ctx.fillStyle = '#06050a';
  ctx.beginPath(); ctx.ellipse(3, -66, 7, 6, 0, 0, TAU); ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = '#ff4757';
  ctx.shadowColor = '#ff3344';
  ctx.shadowBlur = 6;
  ctx.beginPath(); ctx.ellipse(5.5, -67, 2.4, 1.1, -0.1, 0, TAU); ctx.fill();
  ctx.restore();

  // katana arm
  let angle = -2.1;
  if (e.state === 'windup') angle = lerp(-2.2, -2.9, wind);
  else if (e.state === 'attack') angle = lerp(-2.9, 0.7, easeOutCubic(Math.min(1, attack * 2.4)));
  else if (walking) angle = -2.35 + Math.sin(phase) * 0.08;
  const sx = 6, sy = -56;
  const hx = sx + Math.cos(angle) * 15;
  const hy = sy + Math.sin(angle) * 15;
  ctx.strokeStyle = '#14101a';
  ctx.lineWidth = 6.5;
  ctx.beginPath();
  ctx.moveTo(sx, sy);
  ctx.quadraticCurveTo(sx + 6, sy + 8, hx, hy);
  ctx.stroke();
  // glowing red blade
  ctx.save();
  ctx.translate(hx, hy);
  ctx.rotate(angle);
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = 'rgba(255,70,80,0.2)';
  ctx.lineWidth = 7;
  ctx.beginPath(); ctx.moveTo(2, 0); ctx.lineTo(45, 0); ctx.stroke();
  ctx.globalCompositeOperation = 'source-over';
  ctx.strokeStyle = '#d8cfc2';
  ctx.lineWidth = 2.6;
  ctx.beginPath(); ctx.moveTo(2, 0); ctx.lineTo(45, 0); ctx.stroke();
  ctx.strokeStyle = '#ff6a70';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(6, -1); ctx.lineTo(42, -1); ctx.stroke();
  ctx.fillStyle = '#2a1a1a';
  ctx.fillRect(-9, -4, 11, 8);
  ctx.restore();
}

function drawArcher(ctx, e) {
  const t = e.anim;
  const walking = Math.abs(e.vx) > 20;
  const phase = t * (walking ? 9 : 3);
  const stride = walking ? Math.sin(phase) * 7 : 0;
  const aim = e.state === 'aim' ? 1 - e.timer / 0.62 : 0;
  ctx.translate(0, walking ? Math.sin(phase * 2) * 1.2 : Math.sin(t * 2) * 0.6);

  // legs
  ctx.strokeStyle = '#0a1016';
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-3, -28); ctx.lineTo(-7 + stride, -2);
  ctx.moveTo(3, -28); ctx.lineTo(7 - stride, -2);
  ctx.stroke();
  ctx.strokeStyle = '#173a35';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-7 + stride, -4); ctx.lineTo(-3 + stride, -4);
  ctx.moveTo(7 - stride, -4); ctx.lineTo(11 - stride, -4);
  ctx.stroke();

  // tattered cloak
  ctx.fillStyle = '#0b1417';
  ctx.beginPath();
  ctx.moveTo(-10, -50);
  ctx.quadraticCurveTo(-18, -30, -14, -18);
  ctx.lineTo(-3, -26);
  ctx.lineTo(2, -16);
  ctx.lineTo(8, -27);
  ctx.lineTo(12, -20);
  ctx.quadraticCurveTo(15, -38, 9, -52);
  ctx.closePath();
  ctx.fill();

  // torso
  const g = ctx.createLinearGradient(-10, -60, 12, -30);
  g.addColorStop(0, '#071016');
  g.addColorStop(1, '#16302e');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-8, -32);
  ctx.quadraticCurveTo(-12, -50, -5, -58);
  ctx.quadraticCurveTo(4, -62, 9, -52);
  ctx.quadraticCurveTo(11, -40, 6, -32);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(110,255,220,0.4)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(8, -51); ctx.lineTo(6, -33); ctx.stroke();
  // sash
  ctx.fillStyle = '#187a68';
  ctx.fillRect(-8, -36, 16, 3);

  // hooded head
  ctx.fillStyle = '#0b181c';
  ctx.beginPath();
  ctx.ellipse(1, -66, 9, 9.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#071013';
  ctx.beginPath();
  ctx.moveTo(-8, -70);
  ctx.quadraticCurveTo(1, -84, 10, -68);
  ctx.quadraticCurveTo(1, -74, -8, -66);
  ctx.closePath();
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = '#63ffe0';
  ctx.shadowColor = '#52ffe0';
  ctx.shadowBlur = 6;
  ctx.beginPath(); ctx.ellipse(5, -67, 2.2, 1.1, 0, 0, TAU); ctx.fill();
  ctx.restore();
  // scarf tail
  ctx.strokeStyle = '#1a9c84';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(-7, -70);
  ctx.quadraticCurveTo(-16, -66, -20, -58 + Math.sin(t * 6) * 3);
  ctx.stroke();

  // bow
  const bowX = 13;
  const bowY = -45;
  ctx.save();
  ctx.translate(bowX, bowY);
  ctx.strokeStyle = '#8c6a3e';
  ctx.lineWidth = 2.4;
  ctx.beginPath();
  ctx.arc(0, 0, 22, -1.15, 1.15);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(160,255,230,0.5)';
  ctx.lineWidth = 1;
  const pull = aim * 9;
  ctx.beginPath();
  ctx.moveTo(8.4, -20.5);
  ctx.lineTo(-pull, 0);
  ctx.lineTo(8.4, 20.5);
  ctx.stroke();
  if (e.state === 'aim' || e.state === 'shoot') {
    ctx.strokeStyle = '#bffcf0';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-pull, 0);
    ctx.lineTo(26, 0);
    ctx.stroke();
    ctx.fillStyle = '#eafff8';
    ctx.beginPath();
    ctx.moveTo(30, 0); ctx.lineTo(24, -3); ctx.lineTo(24, 3);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  // arm
  ctx.strokeStyle = '#0d1a1c';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.moveTo(4, -52);
  ctx.quadraticCurveTo(12, -47, 13, -45);
  ctx.stroke();
  // quiver
  ctx.save();
  ctx.rotate(-0.25);
  ctx.fillStyle = '#173a34';
  ctx.fillRect(-16, -55, 6, 22);
  ctx.strokeStyle = '#8ef5dd';
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-14 + i * 2, -55);
    ctx.lineTo(-16 + i * 2, -62);
    ctx.stroke();
  }
  ctx.restore();
}

function drawBrute(ctx, e) {
  const t = e.anim;
  const wind = e.state === 'windup' ? 1 - e.timer / 0.68 : 0;
  const swing = e.state === 'attack' ? 1 - e.timer / 0.36 : 0;
  const walking = Math.abs(e.vx) > 15;
  const phase = t * 6;
  const bob = walking ? Math.sin(phase * 2) * 2 : Math.sin(t * 2) * 1;
  ctx.translate(0, bob);

  // legs
  const stride = walking ? Math.sin(phase) * 8 : 0;
  ctx.strokeStyle = '#120d16';
  ctx.lineWidth = 16;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-13, -42); ctx.lineTo(-18 + stride, -4);
  ctx.moveTo(13, -42); ctx.lineTo(18 - stride, -4);
  ctx.stroke();
  ctx.strokeStyle = '#2a1820';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(-18 + stride - 5, -4); ctx.lineTo(-12 + stride, -4);
  ctx.moveTo(18 - stride - 5, -4); ctx.lineTo(24 - stride, -4);
  ctx.stroke();

  // giant torso
  const g = ctx.createLinearGradient(-28, -92, 26, -32);
  g.addColorStop(0, '#0d0811');
  g.addColorStop(0.5, '#261420');
  g.addColorStop(1, '#3a1d28');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-22, -38);
  ctx.quadraticCurveTo(-32, -66, -20, -84);
  ctx.quadraticCurveTo(0, -96, 20, -84);
  ctx.quadraticCurveTo(32, -64, 22, -38);
  ctx.quadraticCurveTo(0, -30, -22, -38);
  ctx.closePath();
  ctx.fill();
  // armor plates
  ctx.strokeStyle = 'rgba(255,110,80,0.22)';
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-18 + i * 2, -76 + i * 10);
    ctx.quadraticCurveTo(0, -70 + i * 10, 18 - i * 2, -76 + i * 10);
    ctx.stroke();
  }
  // glowing cracks
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = 'rgba(255,90,70,0.6)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(-6, -82); ctx.lineTo(2, -70); ctx.lineTo(-4, -60); ctx.lineTo(8, -50);
  ctx.stroke();
  ctx.restore();
  // belt/skirt
  ctx.fillStyle = '#160d14';
  ctx.fillRect(-22, -42, 44, 8);
  // shoulders
  ctx.fillStyle = '#1a1018';
  ctx.beginPath(); ctx.ellipse(-26, -76, 12, 10, -0.4, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(26, -76, 12, 10, 0.4, 0, TAU); ctx.fill();

  // head + oni mask
  ctx.fillStyle = '#161018';
  ctx.beginPath(); ctx.ellipse(0, -94, 13, 13, 0, 0, TAU); ctx.fill();
  // white mask
  ctx.fillStyle = '#cbbfa8';
  ctx.beginPath();
  ctx.ellipse(3, -94, 10, 11, 0.05, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#1a0d12';
  ctx.beginPath();
  ctx.ellipse(5, -92, 6.5, 4, 0, 0, TAU);
  ctx.fill();
  // horns
  ctx.strokeStyle = '#caa982';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-5, -102); ctx.quadraticCurveTo(-16, -118, -10, -124);
  ctx.moveTo(8, -102); ctx.quadraticCurveTo(20, -116, 14, -124);
  ctx.stroke();
  // glowing eyes
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = '#ff4d3d';
  ctx.shadowColor = '#ff3a30';
  ctx.shadowBlur = 8;
  ctx.beginPath(); ctx.ellipse(3, -95, 2.6, 1.4, 0, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.ellipse(10, -95, 2.6, 1.4, 0, 0, TAU); ctx.fill();
  ctx.restore();

  // club arm
  let angle = -1.0;
  if (e.state === 'windup') angle = lerp(-1.0, -2.3, wind);
  else if (e.state === 'attack') angle = lerp(-2.3, 1.1, Math.min(1, swing * 2));
  const sx = 24, sy = -72;
  const hx = sx + Math.cos(angle) * 20;
  const hy = sy + Math.sin(angle) * 20;
  ctx.strokeStyle = '#1a1018';
  ctx.lineWidth = 12;
  ctx.beginPath();
  ctx.moveTo(sx, sy);
  ctx.quadraticCurveTo(sx + 10, sy + 10, hx, hy);
  ctx.stroke();
  // club
  ctx.save();
  ctx.translate(hx, hy);
  ctx.rotate(angle);
  ctx.fillStyle = '#241318';
  ctx.fillRect(-6, -5, 34, 10);
  ctx.beginPath();
  ctx.moveTo(28, -13);
  ctx.lineTo(56, -16);
  ctx.lineTo(60, 0);
  ctx.lineTo(56, 16);
  ctx.lineTo(28, 13);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#7d6a5c';
  ctx.beginPath();
  ctx.moveTo(48, -16); ctx.lineTo(56, -8); ctx.lineTo(50, -2);
  ctx.lineTo(48, -16);
  ctx.fill();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.35 + wind * 0.5;
  ctx.strokeStyle = '#ff5a3c';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(32, 0); ctx.lineTo(54, 0); ctx.stroke();
  ctx.restore();
  ctx.restore();
}

// ----------------------------------------------------------------------------
// PROJECTILES
// ----------------------------------------------------------------------------
export class Projectile {
  constructor(opts) {
    Object.assign(this, {
      type: 'arrow', x: 0, y: 0, vx: 0, vy: 0, r: 6, damage: 10,
      life: 2, maxLife: 2, color: '#ff9b6a', gravity: 0, dead: false,
      phase: rand(0, TAU), owner: 'enemy', destructible: true,
    }, opts);
    this.maxLife = this.life;
  }

  update(dt, game) {
    if (this.dead) return;
    this.life -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    if (this.gravity) this.vy += this.gravity * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.phase += dt * 6;

    if (this.type === 'shock') {
      this.y = GROUND_Y;
      if (game.player.onGround && Math.abs(game.player.x - this.x) < this.r + 16 &&
          Math.abs(game.player.y - GROUND_Y) < 60) {
        if (game.player.takeDamage(this.damage, sign(this.vx))) this.dead = true;
      }
      if (Math.random() < dt * 20) {
        game.fx.dust(this.x, GROUND_Y, -sign(this.vx), 1);
      }
    } else if (this.type === 'rain') {
      if (this.y > GROUND_Y - 4) {
        this.dead = true;
        game.fx.ring(this.x, GROUND_Y - 8, 'rgba(255,80,90,0.75)', 40, 3, 0.32);
        game.fx.spark(this.x, GROUND_Y - 8, '#ff5c6e', 7, 240);
        game.shake(0.1);
        if (Math.abs(game.player.x - this.x) < 42 && game.player.y > GROUND_Y - 70) {
          game.player.takeDamage(this.damage, sign(this.x - game.player.x));
        }
      }
    } else {
      if (circleRect(this.x, this.y, this.r, game.player.rect)) {
        if (game.player.takeDamage(this.damage, sign(this.vx || 1))) this.dead = true;
      }
    }
    if (this.x < -80 || this.x > WORLD_W + 80 || this.y > GROUND_Y + 80) this.dead = true;
    if (this.type === 'orb' && Math.random() < dt * 12) {
      game.fx.ember(this.x, this.y, this.color, 1, 20, 0.5);
    }
  }

  draw(ctx) {
    if (this.dead) return;
    const fade = clamp(this.life / Math.min(this.maxLife, 0.5), 0, 1);
    ctx.save();
    if (this.type === 'shock') {
      const p = 1 - this.life / this.maxLife;
      const dir = sign(this.vx);
      ctx.translate(this.x, this.y);
      ctx.scale(dir, 1);
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.85 * fade;
      for (let i = 0; i < 3; i++) {
        ctx.strokeStyle = i === 0 ? '#fff2e0' : this.color;
        ctx.lineWidth = 4 - i;
        ctx.beginPath();
        ctx.arc(0, 0, 26 + i * 6, -1.2, 0.1);
        ctx.stroke();
      }
      ctx.fillStyle = `rgba(255,90,60,${0.16 * fade})`;
      ctx.beginPath(); ctx.ellipse(0, -18, 44, 30, 0, 0, TAU); ctx.fill();
      ctx.restore();
      return;
    }
    if (this.type === 'rain') {
      ctx.translate(this.x, this.y);
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = fade;
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.ellipse(0, 0, this.r * 0.7, this.r * 2.4, 0, 0, TAU);
      ctx.fill();
      ctx.globalAlpha = 0.22;
      ctx.beginPath(); ctx.arc(0, 0, this.r * 3, 0, TAU); ctx.fill();
      ctx.restore();
      return;
    }
    const ang = Math.atan2(this.vy, this.vx);
    ctx.translate(this.x, this.y);
    if (this.type === 'arrow') {
      ctx.rotate(ang);
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = this.color;
      ctx.globalAlpha = 0.35 * fade;
      ctx.lineWidth = 6;
      ctx.beginPath(); ctx.moveTo(-30, 0); ctx.lineTo(4, 0); ctx.stroke();
      ctx.globalAlpha = 0.9 * fade;
      ctx.strokeStyle = '#ffe8d0';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(-14, 0); ctx.lineTo(6, 0); ctx.stroke();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.moveTo(9, 0); ctx.lineTo(3, -3); ctx.lineTo(3, 3); ctx.closePath(); ctx.fill();
    } else {
      // orb
      const r = this.r;
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = fade;
      const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 4);
      g.addColorStop(0, '#ffffff');
      g.addColorStop(0.25, this.color);
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(0, 0, r * 4, 0, TAU); ctx.fill();
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(0, 0, r * 0.55, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }
}

// ----------------------------------------------------------------------------
// PICKUPS
// ----------------------------------------------------------------------------
export class Pickup {
  constructor(type, x, y) {
    this.type = type;
    this.x = x;
    this.y = y;
    this.vy = -180;
    this.phase = rand(0, TAU);
    this.life = 14;
    this.dead = false;
    this.grounded = false;
  }

  update(dt, game) {
    this.life -= dt;
    if (this.life <= 0) this.dead = true;
    this.phase += dt * 3;
    if (!this.grounded) {
      this.vy += GRAVITY * 0.6 * dt;
      this.y += this.vy * dt;
      if (this.y >= GROUND_Y - 18) {
        this.y = GROUND_Y - 18;
        this.vy = 0;
        this.grounded = true;
      }
    }
    const p = game.player;
    if (Math.abs(p.x - this.x) < 38 && Math.abs(p.y - 34 - this.y) < 56) {
      this.dead = true;
      if (this.type === 'health') {
        p.heal(22);
        game.fx.text(this.x, this.y - 20, '+22', '#8dffc8', 20);
        game.fx.ring(this.x, this.y, 'rgba(110,255,190,0.8)', 50, 2, 0.3);
      } else {
        p.addFocus(40);
        game.fx.text(this.x, this.y - 20, '+40 FOCUS', '#9ef7ff', 16);
        game.fx.ring(this.x, this.y, 'rgba(110,220,255,0.8)', 50, 2, 0.3);
      }
      game.sound.sfx('pickup');
      game.fx.ember(this.x, this.y, this.type === 'health' ? '#7dffc0' : '#8ee8ff', 7, 120);
    }
  }

  draw(ctx) {
    const bob = Math.sin(this.phase * 2) * 3;
    const a = this.life < 3 ? (0.4 + Math.sin(this.life * 18) * 0.35) : 1;
    ctx.save();
    ctx.globalAlpha = Math.max(0.15, a);
    ctx.translate(this.x, this.y + bob);
    const col = this.type === 'health' ? '#67ffb0' : '#7de8ff';
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 34);
    g.addColorStop(0, col);
    g.addColorStop(0.4, this.type === 'health' ? 'rgba(80,255,170,0.32)' : 'rgba(90,220,255,0.32)');
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, 34, 0, TAU); ctx.fill();
    ctx.globalAlpha *= 0.95;
    ctx.fillStyle = this.type === 'health' ? 'rgba(20,80,45,0.9)' : 'rgba(20,50,80,0.9)';
    ctx.beginPath(); ctx.arc(0, 0, 8, 0, TAU); ctx.fill();
    ctx.strokeStyle = col;
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.arc(0, 0, 8, 0, TAU); ctx.stroke();
    ctx.fillStyle = '#eafff4';
    if (this.type === 'health') {
      ctx.fillRect(-1.6, -4, 3.2, 8);
      ctx.fillRect(-4, -1.6, 8, 3.2);
    } else {
      ctx.beginPath();
      ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0);
      ctx.closePath(); ctx.fill();
    }
    ctx.restore();
  }
}

// SHADOW NINJA — Kagemasa, the Oni Shogun (multi-phase boss)

import { TAU, GROUND_Y, WORLD_W, clamp, lerp, rand, pick, sign, easeOutCubic, circleRect } from './utils.js';

export class Boss {
  constructor(game, x, wave) {
    this.game = game;
    this.type = 'boss';
    this.name = 'KAGEMASA';
    this.title = 'THE ONI SHOGUN';
    this.w = 110;
    this.h = 168;
    this.x = x;
    this.y = GROUND_Y;
    this.vx = 0;
    this.vy = 0;
    this.facing = -1;
    this.maxHp = 880;
    this.hp = this.maxHp;
    this.phase = 1;
    this.state = 'intro';
    this.timer = 2.4;
    this.pattern = null;
    this.patternT = 0;
    this.didDamage = false;
    this.hitFlash = 0;
    this.invuln = 2.6;
    this.dead = false;
    this.deathTimer = 0;
    this.anim = 0;
    this.alpha = 1;
    this.lastPattern = '';
    this.actionTick = 0;
    this.summonedThisPattern = false;
    this.phaseBurstDone = false;
    this.telegraph = 0;
    this.telegraphType = '';
    this.scoreValue = 6000;
    this.id = 99999;
  }

  get rect() {
    return { x: this.x - 46, y: this.y - 150, w: 92, h: 150 };
  }

  get alive() {
    return !this.dead;
  }

  update(dt, game) {
    this.anim += dt;
    if (this.dead) {
      this.deathTimer += dt;
      this.vy += 1200 * dt;
      this.y = Math.min(GROUND_Y, this.y + this.vy * dt);
      this.vx *= Math.exp(-3 * dt);
      this.x += this.vx * dt;
      if (this.deathTimer < 2.6 && Math.random() < dt * 7) {
        const ex = this.x + rand(-70, 70);
        const ey = this.y - rand(20, 150);
        game.fx.ember(ex, ey, pick(['#ff6a55', '#ffb26b', '#ff3355']), 12, 320, 1.1);
        game.fx.spark(ex, ey, '#ffe8c0', 5, 300);
        game.fx.smoke(ex, ey, '70,40,50', 2, 24);
        game.shake(0.2);
      }
      return;
    }
    this.hitFlash = Math.max(0, this.hitFlash - dt);
    this.invuln = Math.max(0, this.invuln - dt);
    this.telegraph = Math.max(0, this.telegraph - dt);
    const player = game.player;
    const dx = player.x - this.x;
    const adx = Math.abs(dx);
    const dir = sign(dx || 1);

    if (this.state !== 'action' && this.state !== 'windup' && this.state !== 'phase') {
      this.facing = dir;
    }

    // gravity / ground
    this.vy += 2400 * dt;
    this.y = Math.min(GROUND_Y, this.y + this.vy * dt);
    if (this.y >= GROUND_Y) { this.y = GROUND_Y; this.vy = 0; }

    switch (this.state) {
      case 'intro': {
        this.timer -= dt;
        this.vx *= Math.exp(-6 * dt);
        if (this.timer <= 0) {
          this.state = 'idle';
          this.timer = 0.7;
          game.sound.sfx('roar');
          game.shake(0.5);
          game.fx.ring(this.x, this.y - 40, 'rgba(255,60,70,0.9)', 220, 7, 0.8, 20);
          game.fx.ember(this.x, this.y - 90, '#ff5b4a', 40, 340, 1.6);
          this.invuln = 0.4;
        }
        break;
      }
      case 'idle': {
        this.timer -= dt;
        this.vx = lerp(this.vx, 0, Math.min(1, dt * 6));
        if (adx > 280) this.vx = lerp(this.vx, dir * 95, Math.min(1, dt * 4));
        else if (adx < 130) this.vx = lerp(this.vx, -dir * 55, Math.min(1, dt * 3));
        if (this.timer <= 0) this.choosePattern(game, player, adx);
        break;
      }
      case 'windup': {
        this.timer -= dt;
        this.vx *= Math.exp(-8 * dt);
        this.updateWindupFx(dt, game, player);
        if (this.timer <= 0) this.startAction(game, player);
        break;
      }
      case 'action':
        this.updateAction(dt, game, player);
        break;
      case 'recover': {
        this.timer -= dt;
        this.vx *= Math.exp(-7 * dt);
        if (this.timer <= 0) {
          this.state = 'idle';
          this.timer = this.phase >= 3 ? 0.28 : this.phase >= 2 ? 0.42 : 0.55;
        }
        break;
      }
      case 'phase': {
        this.timer -= dt;
        this.vx *= Math.exp(-9 * dt);
        if (!this.phaseBurstDone && this.timer < 0.95) {
          this.phaseBurstDone = true;
          this.phaseBurst(game, player);
        }
        if (this.timer <= 0) {
          this.state = 'idle';
          this.timer = 0.3;
          this.alpha = 1;
          this.invuln = 0.2;
        }
        break;
      }
    }

    this.x += this.vx * dt;
    this.x = clamp(this.x, 180, WORLD_W - 120);
  }

  choosePattern(game, player, adx) {
    const pool = ['dashSlash', 'fanVolley', 'slam'];
    if (this.phase >= 2) {
      pool.push('teleportSlash');
      if (game.enemies.filter((e) => !e.dead && e.type !== 'boss').length < 3) pool.push('summon');
    }
    if (this.phase >= 3) pool.push('rain', 'fanVolley');
    let choices = pool.filter((p) => p !== this.lastPattern);
    if (!choices.length) choices = pool;
    const pattern = pick(choices);
    this.lastPattern = pattern;
    this.pattern = pattern;
    this.state = 'windup';
    this.didDamage = false;
    this.summonedThisPattern = false;
    this.actionTick = 0;

    if (pattern === 'dashSlash') {
      this.timer = this.phase >= 3 ? 0.44 : 0.58;
      this.telegraph = 0.58;
      this.telegraphType = 'line';
      this.facing = sign(player.x - this.x) || 1;
      game.sound.sfx('click');
    } else if (pattern === 'fanVolley') {
      this.timer = 0.5;
      this.telegraph = 0.5;
      this.telegraphType = 'fan';
    } else if (pattern === 'slam') {
      this.timer = 0.62;
      this.telegraph = 0.62;
      this.telegraphType = 'circle';
      game.sound.sfx('click');
    } else if (pattern === 'teleportSlash') {
      this.timer = 0.5;
      this.telegraph = 0.5;
      this.telegraphType = 'none';
      game.fx.smoke(this.x, this.y - 70, '90,30,50', 8, 30);
      game.sound.sfx('dash');
    } else if (pattern === 'summon') {
      this.timer = 0.7;
      this.telegraph = 0.7;
      this.telegraphType = 'circle';
    } else if (pattern === 'rain') {
      this.timer = 0.55;
      this.telegraph = 0.55;
      this.telegraphType = 'rain';
      this.facing = sign(player.x - this.x) || 1;
    }
  }

  updateWindupFx(dt, game, player) {
    if (this.pattern === 'teleportSlash') {
      this.alpha = lerp(this.alpha, 0, Math.min(1, dt * 6));
      if (Math.random() < dt * 30) game.fx.ember(this.x + rand(-40, 40), this.y - rand(10, 150), '#c53a65', 3, 140);
    } else if (this.pattern === 'rain') {
      if (Math.random() < dt * 28) game.fx.ember(this.x + rand(-70, 70), this.y - rand(20, 160), '#ff4f60', 2, 90);
    } else if (this.pattern === 'dashSlash' && Math.random() < dt * 22) {
      game.fx.spark(this.x + rand(-40, 40), this.y - rand(20, 150), '#ff7a6a', 1, 80, { grav: -80 });
    } else if (this.pattern === 'slam' && Math.random() < dt * 20) {
      game.fx.dust(this.x + rand(-60, 60), this.y, 0, 1);
    }
  }

  startAction(game, player) {
    this.state = 'action';
    this.patternT = 0;
    this.actionTick = 0;
    this.didDamage = false;
    const p = this.pattern;

    if (p === 'dashSlash') {
      this.timer = 0.5;
      this.facing = sign(player.x - this.x) || 1;
      this.vx = this.facing * (this.phase >= 3 ? 1180 : 980);
      game.sound.sfx('slashHeavy');
      game.shake(0.42);
      game.fx.slash(this.x + this.facing * 40, this.y - 80, this.facing > 0 ? 0 : Math.PI, 130, '#ff5a6e', 0.35, 16, 2.6);
      game.fx.ring(this.x, this.y - 80, 'rgba(255,60,70,0.8)', 110, 5, 0.4);
    } else if (p === 'fanVolley') {
      this.timer = 0.62;
      this.fireFan(game, player);
      this.actionTick = 0.2;
    } else if (p === 'slam') {
      this.timer = 0.5;
      this.doSlam(game, player);
    } else if (p === 'teleportSlash') {
      // appear behind the player
      const behind = player.x - player.facing * 115;
      this.x = clamp(behind, 260, WORLD_W - 200);
      this.y = GROUND_Y;
      this.facing = sign(player.x - this.x) || 1;
      this.alpha = 1;
      this.timer = 0.52;
      this.vx = this.facing * 620;
      this.didDamage = false;
      game.fx.smoke(this.x, this.y - 80, '100,30,55', 12, 38);
      game.fx.ring(this.x, this.y - 60, 'rgba(255,70,90,0.9)', 100, 4, 0.35);
      game.fx.slash(this.x + this.facing * 40, this.y - 80, this.facing > 0 ? -0.1 : Math.PI + 0.1, 130, '#ff5068', 0.34, 14, 2.4);
      game.sound.sfx('slashHeavy');
      game.shake(0.36);
    } else if (p === 'summon') {
      this.timer = 0.55;
      game.spawnBossMinions(this, 2);
      game.sound.sfx('roar');
      game.shake(0.3);
    } else if (p === 'rain') {
      this.timer = 1.6;
      this.actionTick = 0;
      game.sound.sfx('roar');
      game.shake(0.3);
      game.fx.ring(this.x, this.y - 90, 'rgba(255,50,70,0.85)', 150, 5, 0.5);
    }
  }

  fireFan(game, player) {
    const n = this.phase >= 3 ? 7 : 5;
    const base = Math.atan2((player.y - 34) - (this.y - 95), player.x - this.x);
    const spread = 0.72;
    for (let i = 0; i < n; i++) {
      const a = base + (i - (n - 1) / 2) * (spread / (n - 1)) * 2;
      game.spawnEnemyProjectile({
        type: 'orb',
        x: this.x + Math.cos(a) * 50,
        y: this.y - 100 + Math.sin(a) * 50,
        vx: Math.cos(a) * (this.phase >= 3 ? 500 : 430),
        vy: Math.sin(a) * (this.phase >= 3 ? 500 : 430),
        r: 9, damage: Math.round(12 + this.phase * 2),
        life: 3.2, color: '#ff4d64', owner: 'boss',
      });
    }
    game.sound.sfx('slash', 0.9);
    game.shake(0.2);
  }

  doSlam(game, player) {
    game.shake(0.72);
    game.sound.sfx('slam');
    game.fx.screenFlash(0.22, '255,90,70');
    const sx = this.x + this.facing * 60;
    for (let i = 0; i < 2; i++) {
      game.fx.ring(sx, GROUND_Y, 'rgba(255,90,60,0.9)', 190, 6, 0.5, 12);
      game.fx.shards(sx, GROUND_Y - 4, '#ff8a60', 12, 400);
    }
    game.fx.smoke(sx, GROUND_Y, '90,60,60', 9, 32);
    game.fx.ember(sx, GROUND_Y - 10, '#ff6a50', 22, 320);
    game.spawnEnemyProjectile({
      type: 'shock', x: sx, y: GROUND_Y, vx: 620, vy: 0, r: 28,
      damage: 16, life: 1.5, color: '#ff6a55',
    });
    game.spawnEnemyProjectile({
      type: 'shock', x: sx, y: GROUND_Y, vx: -620, vy: 0, r: 28,
      damage: 16, life: 1.5, color: '#ff6a55',
    });
    if (Math.abs(player.x - sx) < 170 && player.y > GROUND_Y - 130) {
      player.takeDamage(24, sign(player.x - this.x));
    }
    if (this.phase >= 3) {
      setTimeout(() => {}, 0);
      for (let i = 0; i < 6; i++) {
        const a = -Math.PI / 2 + (i - 2.5) * 0.22;
        game.spawnEnemyProjectile({
          type: 'orb', x: sx, y: GROUND_Y - 20,
          vx: Math.cos(a) * 330, vy: Math.sin(a) * 330,
          r: 8, damage: 11, life: 2.5, color: '#ff8a4d',
        });
      }
    }
  }

  updateAction(dt, game, player) {
    this.patternT += dt;
    this.timer -= dt;

    switch (this.pattern) {
      case 'dashSlash': {
        this.vx *= Math.exp(-1.4 * dt);
        if (Math.random() < dt * 40) {
          game.fx.ghost(this.x + rand(-30, 30), this.y, this.facing, '255,90,80', 0.24, 1.4);
          game.fx.ember(this.x - this.facing * 30, this.y - rand(20, 140), '#ff6a55', 2, 120);
        }
        if (!this.didDamage) {
          const hit = { x: this.x + this.facing * 25, y: this.y - 80, r: 70 };
          if (circleRect(hit.x, hit.y, hit.r, player.rect)) {
            if (player.takeDamage(20 + this.phase * 3, this.facing)) this.didDamage = true;
          }
        }
        if (this.timer <= 0) {
          this.endAction(game, 0.75);
        }
        break;
      }
      case 'fanVolley': {
        this.vx *= Math.exp(-10 * dt);
        this.actionTick -= dt;
        if (this.actionTick <= 0) {
          this.actionTick = 0.22;
          if (this.patternT < 0.4) this.fireFan(game, player);
        }
        if (this.timer <= 0) this.endAction(game, 0.6);
        break;
      }
      case 'slam': {
        this.vx *= Math.exp(-10 * dt);
        if (this.timer <= 0) this.endAction(game, 0.9);
        break;
      }
      case 'teleportSlash': {
        this.vx *= Math.exp(-2.5 * dt);
        if (!this.didDamage) {
          const hit = { x: this.x + this.facing * 55, y: this.y - 80, r: 82 };
          if (circleRect(hit.x, hit.y, hit.r, player.rect)) {
            if (player.takeDamage(18 + this.phase * 3, this.facing)) this.didDamage = true;
          }
        }
        if (this.timer <= 0) {
          this.vx = 0;
          this.endAction(game, 0.55);
        }
        break;
      }
      case 'summon': {
        this.vx *= Math.exp(-10 * dt);
        if (this.timer <= 0) this.endAction(game, 0.5);
        break;
      }
      case 'rain': {
        this.vx *= Math.exp(-10 * dt);
        this.actionTick -= dt;
        if (this.actionTick <= 0 && this.patternT < 1.35) {
          this.actionTick = 0.11;
          const x = clamp(player.x + rand(-330, 330), 60, WORLD_W - 60);
          game.spawnEnemyProjectile({
            type: 'rain', x, y: -20, vx: rand(-20, 20), vy: 420,
            r: 8, damage: 13, life: 4, gravity: 520, color: '#ff4d5e', owner: 'boss',
          });
          game.fx.ring(x, GROUND_Y - 2, 'rgba(255,70,80,0.5)', 34, 2, 0.5);
        }
        if (this.timer <= 0) this.endAction(game, 0.7);
        break;
      }
    }
  }

  endAction(game, recover) {
    this.state = 'recover';
    this.timer = recover;
    this.pattern = null;
    this.telegraphType = '';
    this.telegraph = 0;
    this.alpha = 1;
  }

  phaseBurst(game, player) {
    game.shake(0.7);
    game.sound.sfx('roar');
    game.fx.screenFlash(0.35, '255,80,80');
    game.fx.ring(this.x, this.y - 80, 'rgba(255,90,80,0.95)', 260, 8, 0.7, 14);
    game.fx.ring(this.x, this.y - 80, 'rgba(255,220,180,0.7)', 170, 4, 0.5, 10);
    game.fx.ember(this.x, this.y - 80, '#ff5a4a', 32, 380, 1.6);
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU;
      game.spawnEnemyProjectile({
        type: 'orb', x: this.x, y: this.y - 80,
        vx: Math.cos(a) * 330, vy: Math.sin(a) * 330,
        r: 8, damage: 10, life: 2.2, color: '#ff6a55', owner: 'boss',
      });
    }
    if (Math.abs(player.x - this.x) < 240) {
      player.takeDamage(10, sign(player.x - this.x));
    }
  }

  takeDamage(dmg, dir, game, opts = {}) {
    if (this.dead || this.invuln > 0) return false;
    this.hp = Math.max(0, this.hp - dmg);
    this.hitFlash = 0.12;
    this.vx += dir * 12;
    game.fx.ember(this.x + rand(-30, 30), this.y - 100 + rand(-30, 30), '#ffb08a', 4, 140);
    if (this.hp <= 0) {
      this.die(game, dir);
    } else if (this.phase === 1 && this.hp <= this.maxHp * 0.6) {
      this.beginPhase(2, game);
    } else if (this.phase === 2 && this.hp <= this.maxHp * 0.3) {
      this.beginPhase(3, game);
    }
    return true;
  }

  beginPhase(n, game) {
    this.phase = n;
    this.state = 'phase';
    this.timer = 1.5;
    this.phaseBurstDone = false;
    this.invuln = 1.6;
    this.vx = 0;
    this.alpha = 1;
    this.telegraph = 0;
    this.pattern = null;
    game.onBossPhase(n);
  }

  die(game, dir) {
    this.dead = true;
    this.hp = 0;
    this.deathTimer = 0;
    this.vx = dir * 120;
    game.onBossKilled(this);
  }

  draw(ctx) {
    if (this.alpha <= 0.01) { this.drawTelegraph(ctx); return; }
    const t = this.anim;
    const walking = Math.abs(this.vx) > 30;
    const phaseT = t * (walking ? 7 : 2);
    const bob = walking ? Math.sin(phaseT * 2) * 2 : Math.sin(t * 1.6) * 1.2;
    const wind = this.state === 'windup' ? 1 - this.timer / Math.max(0.2, this.telegraph || 0.5) : 0;
    const action = this.state === 'action' ? 1 : 0;
    const phaseColor = this.phase === 1 ? '#ff4d5e' : this.phase === 2 ? '#ff7a3d' : '#ff3d8a';

    ctx.save();
    ctx.globalAlpha = this.alpha;
    ctx.translate(this.x, this.y);

    // aura
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const auraR = 170 + Math.sin(t * 3) * 12 + (this.state === 'phase' ? 90 : 0);
    const ag = ctx.createRadialGradient(0, -90, 10, 0, -90, auraR);
    ag.addColorStop(0, this.phase === 3 ? 'rgba(255,60,120,0.24)' : 'rgba(255,60,60,0.20)');
    ag.addColorStop(0.55, 'rgba(160,20,40,0.10)');
    ag.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = ag;
    ctx.beginPath(); ctx.arc(0, -90, auraR, 0, TAU); ctx.fill();
    ctx.restore();

    // ground shadow
    ctx.save();
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.ellipse(0, 2, 62, 13, 0, 0, TAU); ctx.fill();
    ctx.restore();

    ctx.scale(this.facing, 1);
    ctx.translate(0, bob);
    if (this.hitFlash > 0) ctx.filter = 'brightness(2.6) saturate(0.3)';
    if (this.dead) {
      const p = Math.min(1, this.deathTimer * 0.5);
      ctx.rotate(-p * 1.1);
      ctx.translate(0, p * 20);
      ctx.globalAlpha = clamp(1.2 - this.deathTimer * 0.22, 0.25, 1);
    }

    const stride = walking ? Math.sin(phaseT) * 10 : 0;

    // cape
    ctx.save();
    const capeG = ctx.createLinearGradient(0, -140, -80, 20);
    capeG.addColorStop(0, '#2a0a16');
    capeG.addColorStop(0.6, '#4d0e1c');
    capeG.addColorStop(1, '#19060c');
    ctx.fillStyle = capeG;
    ctx.beginPath();
    ctx.moveTo(-20, -140);
    ctx.quadraticCurveTo(-95, -120 + Math.sin(t * 2) * 8, -100, -6);
    ctx.quadraticCurveTo(-70, -22, -52, -4);
    ctx.quadraticCurveTo(-34, -28, -18, -10);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,70,80,0.18)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(-24, -136);
    ctx.quadraticCurveTo(-92, -110, -96, -10);
    ctx.stroke();
    ctx.restore();

    // legs
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#120a10';
    ctx.lineWidth = 24;
    ctx.beginPath();
    ctx.moveTo(-22, -66); ctx.lineTo(-28 + stride, -4);
    ctx.moveTo(22, -66); ctx.lineTo(28 - stride, -4);
    ctx.stroke();
    ctx.strokeStyle = '#2b1720';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(-34 + stride, -4); ctx.lineTo(-20 + stride, -4);
    ctx.moveTo(28 - stride, -4); ctx.lineTo(42 - stride, -4);
    ctx.stroke();
    // shin guards
    ctx.strokeStyle = 'rgba(210,150,90,0.35)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-27 + stride * 0.6, -30); ctx.lineTo(-30 + stride, -10);
    ctx.moveTo(27 - stride * 0.6, -30); ctx.lineTo(30 - stride, -10);
    ctx.stroke();

    // torso
    const bg = ctx.createLinearGradient(-46, -150, 46, -50);
    bg.addColorStop(0, '#0b070d');
    bg.addColorStop(0.5, '#25101b');
    bg.addColorStop(1, '#3b1822');
    ctx.fillStyle = bg;
    ctx.beginPath();
    ctx.moveTo(-38, -62);
    ctx.quadraticCurveTo(-58, -105, -34, -145);
    ctx.quadraticCurveTo(0, -165, 34, -145);
    ctx.quadraticCurveTo(58, -105, 38, -62);
    ctx.quadraticCurveTo(0, -48, -38, -62);
    ctx.closePath();
    ctx.fill();
    // armor plates / gold trim
    ctx.strokeStyle = 'rgba(220,170,95,0.5)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(-30 + i * 4, -132 + i * 20);
      ctx.quadraticCurveTo(0, -120 + i * 20, 30 - i * 4, -132 + i * 20);
      ctx.stroke();
    }
    // chest emblem
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = phaseColor;
    ctx.globalAlpha = 0.55;
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.arc(0, -106, 16, 0, TAU);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, -118); ctx.lineTo(0, -94);
    ctx.moveTo(-8, -106); ctx.lineTo(8, -106);
    ctx.stroke();
    ctx.restore();
    // shoulder pauldrons with spikes
    ctx.fillStyle = '#1b0d14';
    ctx.beginPath(); ctx.ellipse(-40, -136, 20, 16, -0.35, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(40, -136, 20, 16, 0.35, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(255,80,90,0.35)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.ellipse(40, -136, 20, 16, 0.35, 0, TAU); ctx.stroke();
    for (let s = 0; s < 3; s++) {
      ctx.strokeStyle = '#b98754';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(34 + s * 7, -148); ctx.lineTo(40 + s * 8, -160 - s * 3);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-34 - s * 7, -148); ctx.lineTo(-40 - s * 8, -160 - s * 3);
      ctx.stroke();
    }

    // head & oni mask
    ctx.fillStyle = '#10080e';
    ctx.beginPath(); ctx.ellipse(4, -166, 24, 24, 0, 0, TAU); ctx.fill();
    // mane
    ctx.fillStyle = '#0a0509';
    ctx.beginPath();
    ctx.moveTo(-18, -184);
    ctx.quadraticCurveTo(-38, -170, -30, -146);
    ctx.quadraticCurveTo(-18, -160, -12, -156);
    ctx.closePath();
    ctx.fill();
    // horns
    ctx.strokeStyle = '#d9c4a2';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(-10, -184);
    ctx.quadraticCurveTo(-40, -206, -30, -224);
    ctx.moveTo(18, -184);
    ctx.quadraticCurveTo(48, -206, 38, -224);
    ctx.stroke();
    // mask face
    ctx.fillStyle = '#d9cdb5';
    ctx.beginPath();
    ctx.ellipse(6, -164, 17, 20, 0.08, 0, TAU);
    ctx.fill();
    // red mask markings
    ctx.fillStyle = '#8c1124';
    ctx.beginPath();
    ctx.moveTo(-2, -180);
    ctx.quadraticCurveTo(6, -174, 2, -164);
    ctx.quadraticCurveTo(-2, -172, -6, -178);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(120,15,30,0.8)';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(6, -182); ctx.quadraticCurveTo(14, -176, 18, -166);
    ctx.stroke();
    // mouth with fangs
    ctx.fillStyle = '#1b070d';
    ctx.beginPath();
    ctx.ellipse(7, -153, 10, 5, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#f3ead8';
    ctx.beginPath();
    ctx.moveTo(1, -156); ctx.lineTo(4, -150); ctx.lineTo(6, -155);
    ctx.moveTo(9, -155); ctx.lineTo(12, -150); ctx.lineTo(14, -155);
    ctx.fill();
    // eyes
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = phaseColor;
    ctx.shadowColor = phaseColor;
    ctx.shadowBlur = 14;
    ctx.beginPath(); ctx.ellipse(-1, -170, 4.5, 2.2, 0.15, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(13, -170, 4.5, 2.2, -0.15, 0, TAU); ctx.fill();
    ctx.restore();
    // topknot
    ctx.strokeStyle = '#1a0a10';
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(4, -187); ctx.quadraticCurveTo(10, -202, 2, -210);
    ctx.stroke();

    // giant blade
    let bladeAngle = -0.9;
    if (this.state === 'windup') {
      bladeAngle = this.pattern === 'fanVolley' ? lerp(-0.9, -2.1, wind) : lerp(-0.9, -2.4, wind);
    } else if (this.state === 'action') {
      if (this.pattern === 'dashSlash' || this.pattern === 'teleportSlash') bladeAngle = 0.1;
      else if (this.pattern === 'slam') bladeAngle = 1.0;
      else if (this.pattern === 'fanVolley') bladeAngle = -1.3;
      else if (this.pattern === 'rain') bladeAngle = -2.0;
    }
    const sx = 38, sy = -124;
    const hx = sx + Math.cos(bladeAngle) * 28;
    const hy = sy + Math.sin(bladeAngle) * 28;
    ctx.strokeStyle = '#160c12';
    ctx.lineWidth = 15;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo(sx + 10, sy + 14, hx, hy);
    ctx.stroke();
    // hand
    ctx.fillStyle = '#2a1620';
    ctx.beginPath(); ctx.arc(hx, hy, 6, 0, TAU); ctx.fill();
    // blade
    ctx.save();
    ctx.translate(hx, hy);
    ctx.rotate(bladeAngle);
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(255,60,70,0.22)';
    ctx.lineWidth = 18;
    ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(130, -4); ctx.stroke();
    ctx.globalCompositeOperation = 'source-over';
    const bg2 = ctx.createLinearGradient(4, 0, 130, 0);
    bg2.addColorStop(0, '#d7c7ae');
    bg2.addColorStop(0.7, '#f1e6d2');
    bg2.addColorStop(1, '#a9937c');
    ctx.strokeStyle = bg2;
    ctx.lineWidth = 6;
    ctx.beginPath(); ctx.moveTo(4, 0); ctx.lineTo(130, -4); ctx.stroke();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = phaseColor;
    ctx.globalAlpha = 0.8;
    ctx.lineWidth = 1.6;
    ctx.beginPath(); ctx.moveTo(10, -2); ctx.lineTo(126, -6); ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = '#b31f35';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-12, 0); ctx.lineTo(3, 0); ctx.stroke();
    ctx.fillStyle = '#d9b56a';
    ctx.beginPath(); ctx.ellipse(3, 0, 4, 10, 0, 0, TAU); ctx.fill();
    ctx.restore();

    ctx.filter = 'none';
    ctx.restore();

    this.drawTelegraph(ctx);

    // phase transition aura ring
    if (this.state === 'phase') {
      ctx.save();
      ctx.translate(this.x, this.y - 80);
      ctx.globalCompositeOperation = 'lighter';
      const p = 1 - this.timer / 1.5;
      ctx.globalAlpha = 0.5 * (1 - p);
      ctx.strokeStyle = phaseColor;
      ctx.lineWidth = 5;
      ctx.beginPath(); ctx.arc(0, 0, 60 + p * 150, 0, TAU); ctx.stroke();
      ctx.restore();
    }
  }

  drawTelegraph(ctx) {
    if (this.state !== 'windup' || this.telegraphType === 'none') return;
    const player = this.game.player;
    const p = 1 - this.timer / Math.max(0.01, this.telegraph);
    const pulse = 0.35 + Math.sin(this.anim * 26) * 0.2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = this.phase >= 3 ? '#ff4d8a' : '#ff5a4a';
    ctx.fillStyle = this.phase >= 3 ? 'rgba(255,60,120,0.08)' : 'rgba(255,70,60,0.07)';
    ctx.globalAlpha = pulse;
    if (this.telegraphType === 'line') {
      const dir = sign(player.x - this.x) || 1;
      ctx.lineWidth = 3;
      ctx.setLineDash([14, 10]);
      ctx.beginPath();
      ctx.moveTo(this.x + dir * 60, this.y - 80);
      ctx.lineTo(this.x + dir * 620, this.y - 80);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = pulse * 0.5;
      ctx.fillRect(this.x + dir * 60, this.y - 130, dir * 560, 100);
    } else if (this.telegraphType === 'circle') {
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.ellipse(this.x + this.facing * 50, GROUND_Y - 6, 150, 42, 0, 0, TAU);
      ctx.stroke();
      ctx.globalAlpha = pulse * 0.6;
      ctx.beginPath(); ctx.arc(this.x + this.facing * 50, this.y - 50, 90 + p * 40, 0, TAU); ctx.stroke();
    } else if (this.telegraphType === 'fan') {
      const base = Math.atan2((player.y - 34) - (this.y - 95), player.x - this.x);
      ctx.lineWidth = 2;
      for (let i = -3; i <= 3; i++) {
        const a = base + i * 0.18;
        ctx.beginPath();
        ctx.moveTo(this.x + Math.cos(a) * 50, this.y - 100 + Math.sin(a) * 50);
        ctx.lineTo(this.x + Math.cos(a) * 500, this.y - 100 + Math.sin(a) * 500);
        ctx.stroke();
      }
    } else if (this.telegraphType === 'rain') {
      ctx.lineWidth = 2;
      for (let i = 0; i < 4; i++) {
        const x = player.x - 210 + i * 140;
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, GROUND_Y);
        ctx.stroke();
      }
      ctx.globalAlpha = pulse * 0.5;
      ctx.fillRect(player.x - 260, 0, 520, GROUND_Y);
    }
    ctx.restore();
  }
}

